{
  "name": "spider-man-neon-pursuit",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "description": "A stylish 3D web-swinging chase game starring Spider-Man against the Green Goblin.",
  "scripts": {
    "dev": "vite --host 0.0.0.0 --port 3002",
    "build": "vite build",
    "preview": "vite preview --host 0.0.0.0 --port 3002"
  },
  "dependencies": {
    "@fontsource/barlow-condensed": "^5.3.0",
    "@fontsource/rajdhani": "^5.3.0",
    "three": "^0.187.0"
  },
  "devDependencies": {
    "vite": "^8.3.5"
  }
}

:root {
  --ink: #060914;
  --ink-soft: rgba(6, 9, 20, 0.72);
  --panel: rgba(8, 14, 30, 0.7);
  --panel-hard: rgba(8, 14, 30, 0.92);
  --line: rgba(179, 216, 255, 0.2);
  --white: #f4f7ff;
  --muted: #9daec7;
  --red: #ff2948;
  --red-hot: #ff5a62;
  --blue: #2c6dff;
  --web: #d8ecff;
  --green: #7cff65;
  --gold: #ffcf5c;
  --cyan: #70e7ff;
  --font-display: "Barlow Condensed", "Arial Narrow", Impact, sans-serif;
  --font-ui: "Rajdhani", "Trebuchet MS", sans-serif;
  --safe-top: max(18px, env(safe-area-inset-top));
  --safe-bottom: max(18px, env(safe-area-inset-bottom));
}

* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: var(--ink);
  color: var(--white);
  font-family: var(--font-ui);
  -webkit-font-smoothing: antialiased;
  user-select: none;
}

button {
  font: inherit;
  color: inherit;
  border: 0;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

button:focus-visible {
  outline: 2px solid var(--cyan);
  outline-offset: 4px;
}

#app {
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 540px;
  isolation: isolate;
}

#scene {
  position: absolute;
  inset: 0;
}

#scene canvas {
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
}

.is-hidden {
  opacity: 0 !important;
  visibility: hidden !important;
  pointer-events: none !important;
}

.screen-fx {
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 5;
  overflow: hidden;
}

.vignette {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at center, transparent 35%, rgba(0, 0, 0, 0.26) 77%, rgba(0, 0, 0, 0.76) 120%),
    linear-gradient(180deg, rgba(3, 6, 14, 0.3), transparent 18%, transparent 75%, rgba(3, 6, 14, 0.5));
}

.speed-lines {
  position: absolute;
  inset: -20%;
  opacity: 0;
  background: repeating-conic-gradient(from 0deg, transparent 0deg 5.5deg, rgba(219, 241, 255, 0.23) 5.7deg 5.85deg, transparent 6deg 12deg);
  mask-image: radial-gradient(circle at center, transparent 0 30%, black 70%);
  -webkit-mask-image: radial-gradient(circle at center, transparent 0 30%, black 70%);
  transform: scale(1.1);
  transition: opacity 0.2s linear;
  mix-blend-mode: screen;
}

.speed-lines.is-active {
  opacity: 0.55;
  animation: speedspin 0.6s linear infinite;
}

@keyframes speedspin {
  to {
    transform: scale(1.1) rotate(6deg);
  }
}

.damage-flash {
  position: absolute;
  inset: 0;
  opacity: 0;
  background: radial-gradient(ellipse at center, transparent 20%, rgba(255, 20, 48, 0.6) 100%);
  mix-blend-mode: screen;
  transition: opacity 0.3s ease;
}

.damage-flash.is-hit {
  opacity: 1;
  transition: none;
}

.slowmo-grade {
  position: absolute;
  inset: 0;
  opacity: 0;
  background: linear-gradient(180deg, rgba(32, 96, 255, 0.14), transparent 30%, transparent 65%, rgba(255, 36, 74, 0.18));
  mix-blend-mode: screen;
  transition: opacity 0.25s ease;
}

.slowmo-grade.is-active {
  opacity: 1;
}

.cinema-bars {
  position: absolute;
  inset: 0;
  z-index: 40;
  pointer-events: none;
}

.cinema-bars i {
  position: absolute;
  left: 0;
  right: 0;
  height: 0;
  background: #03060d;
  transition: height 0.5s cubic-bezier(0.7, 0, 0.2, 1);
}

.cinema-bars i:first-child {
  top: 0;
}

.cinema-bars i:last-child {
  bottom: 0;
}

.cinema-bars.is-active i {
  height: 8.5vh;
}

/* ---------------- HUD ---------------- */

.hud {
  position: absolute;
  inset: 0;
  z-index: 15;
  pointer-events: none;
  padding: var(--safe-top) 34px var(--safe-bottom);
  transition: opacity 0.35s ease;
}

.hud-top {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: start;
  gap: 24px;
  max-width: 1440px;
  margin: 0 auto;
}

.mission-card {
  justify-self: start;
  position: relative;
  padding: 12px 18px 12px 16px;
  min-width: 300px;
  border-left: 2px solid var(--red);
  background: linear-gradient(90deg, rgba(5, 10, 22, 0.78), rgba(5, 10, 22, 0.12));
}

.chapter-label,
.micro-label,
.eyebrow {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.22em;
  color: var(--muted);
  text-transform: uppercase;
}

.chapter-label {
  color: var(--red-hot);
  margin-bottom: 5px;
}

.objective-row {
  display: flex;
  align-items: center;
  gap: 9px;
  font-family: var(--font-display);
  font-size: clamp(17px, 1.5vw, 22px);
  line-height: 1;
  letter-spacing: 0.055em;
  text-transform: uppercase;
}

.objective-pip {
  width: 7px;
  height: 7px;
  flex: none;
  border-radius: 50%;
  background: var(--red);
  box-shadow: 0 0 0 4px rgba(255, 41, 72, 0.16), 0 0 16px var(--red);
  animation: pipPulse 1.8s ease-in-out infinite;
}

@keyframes pipPulse {
  50% {
    box-shadow: 0 0 0 7px rgba(255, 41, 72, 0), 0 0 22px var(--red);
  }
}

.chase-clock {
  text-align: center;
  min-width: 150px;
  padding: 8px 22px 9px;
  background: linear-gradient(180deg, rgba(5, 10, 22, 0.75), rgba(5, 10, 22, 0.2));
  border-top: 1px solid rgba(255, 255, 255, 0.1);
}

.chase-clock strong {
  display: block;
  font-family: var(--font-display);
  font-size: 34px;
  font-weight: 600;
  line-height: 0.95;
  letter-spacing: 0.08em;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 0 24px rgba(112, 231, 255, 0.28);
}

.chase-clock.is-critical strong {
  color: var(--red-hot);
  animation: clockPulse 1s ease-in-out infinite;
}

@keyframes clockPulse {
  50% {
    opacity: 0.5;
    transform: scale(1.04);
  }
}

.score-card {
  justify-self: end;
  text-align: right;
  padding: 8px 0 8px 18px;
}

.score-card strong {
  display: block;
  font-family: var(--font-display);
  font-size: 32px;
  font-weight: 600;
  letter-spacing: 0.08em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 0 20px rgba(255, 207, 92, 0.2);
}

.status-rail {
  position: absolute;
  left: 34px;
  bottom: var(--safe-bottom);
  width: 252px;
  padding: 16px 18px 14px;
  background: linear-gradient(100deg, rgba(6, 11, 23, 0.83), rgba(6, 11, 23, 0.3));
  border-left: 2px solid rgba(112, 231, 255, 0.42);
  clip-path: polygon(0 0, 100% 0, 94% 100%, 0 100%);
  backdrop-filter: blur(8px);
}

.status-title {
  display: flex;
  justify-content: space-between;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.18em;
  color: var(--muted);
  margin-bottom: 5px;
}

.meter {
  position: relative;
  height: 7px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.08);
  margin-bottom: 11px;
  transform: skewX(-14deg);
}

.meter i {
  position: absolute;
  inset: 0 auto 0 0;
  width: 100%;
  transition: width 0.25s ease;
}

.meter b {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(90deg, transparent 0 21px, rgba(4, 8, 18, 0.65) 21px 24px);
}

.health-meter i {
  background: linear-gradient(90deg, #cb1132, var(--red) 60%, #ff7e6b);
  box-shadow: 0 0 14px rgba(255, 41, 72, 0.45);
}

.web-meter i {
  background: linear-gradient(90deg, #4c8fff, var(--cyan));
  box-shadow: 0 0 14px rgba(112, 231, 255, 0.4);
}

.lives-row {
  display: flex;
  align-items: center;
  gap: 13px;
  margin-top: 2px;
}

.lives-pips {
  display: flex;
  gap: 5px;
}

.lives-pips i {
  width: 18px;
  height: 8px;
  transform: skewX(-22deg);
  background: var(--red);
  box-shadow: 0 0 10px rgba(255, 41, 72, 0.45);
}

.lives-pips i.is-empty {
  background: rgba(255, 255, 255, 0.12);
  box-shadow: none;
}

.goblin-panel {
  position: absolute;
  left: 50%;
  top: 94px;
  transform: translateX(-50%);
  width: min(490px, 40vw);
  padding: 12px 16px 9px;
  background: linear-gradient(180deg, rgba(5, 10, 22, 0.72), rgba(5, 10, 22, 0.22));
  border-top: 1px solid rgba(124, 255, 101, 0.2);
  transition: opacity 0.3s ease;
}

.goblin-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 7px;
}

.goblin-tag {
  display: flex;
  align-items: center;
  gap: 7px;
  font-family: var(--font-display);
  font-size: 17px;
  font-weight: 600;
  letter-spacing: 0.12em;
  color: #caffbc;
}

.goblin-tag i {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 13px var(--green);
}

#distanceText {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}

.goblin-meter {
  position: relative;
  height: 9px;
  transform: skewX(-18deg);
  background: rgba(255, 255, 255, 0.08);
  overflow: hidden;
}

.goblin-meter i {
  position: absolute;
  inset: 0 auto 0 0;
  width: 100%;
  background: linear-gradient(90deg, #3ea824, var(--green) 65%, #d4ff8f);
  box-shadow: 0 0 16px rgba(124, 255, 101, 0.6);
  transition: width 0.35s ease;
}

.goblin-meter b {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(90deg, transparent 0 36px, rgba(4, 8, 18, 0.8) 36px 39px);
}

.goblin-note {
  text-align: center;
  color: rgba(202, 255, 188, 0.64);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.22em;
  margin-top: 6px;
}

.combo-stack {
  position: absolute;
  left: 38px;
  top: 46%;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  opacity: 0;
  transform: translateX(-15px) rotate(-3deg);
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.combo-stack.is-active {
  opacity: 1;
  transform: translateX(0) rotate(-3deg);
}

.combo-stack span {
  font-family: var(--font-display);
  font-size: clamp(48px, 7vw, 90px);
  line-height: 0.72;
  font-weight: 700;
  font-style: italic;
  color: var(--white);
  text-shadow: 4px 4px 0 var(--red), 0 0 32px rgba(255, 41, 72, 0.3);
}

.combo-stack small {
  font-size: 10px;
  letter-spacing: 0.28em;
  color: var(--red-hot);
  font-weight: 700;
  margin-top: 8px;
}

.combo-stack em {
  font-size: 12px;
  letter-spacing: 0.14em;
  color: var(--muted);
  font-style: normal;
  font-weight: 700;
}

.reticle {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 64px;
  height: 64px;
  margin: -32px 0 0 -32px;
  opacity: 0.5;
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.reticle.is-target {
  opacity: 1;
  transform: scale(1.22);
}

.r-dot {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 3px;
  height: 3px;
  margin: -1.5px;
  border-radius: 50%;
  background: var(--white);
  box-shadow: 0 0 9px var(--cyan);
}

.r-ring {
  position: absolute;
  inset: 18px;
  border: 1px solid rgba(230, 244, 255, 0.55);
  border-radius: 50%;
}

.reticle.is-target .r-ring {
  border-color: var(--green);
  box-shadow: 0 0 12px rgba(124, 255, 101, 0.5);
}

.r-tick {
  position: absolute;
  width: 8px;
  height: 1px;
  background: rgba(230, 244, 255, 0.72);
}

.r-tick.t1 {
  left: 0;
  top: 31px;
}
.r-tick.t2 {
  right: 0;
  top: 31px;
}
.r-tick.t3 {
  left: 31px;
  top: 0;
  width: 1px;
  height: 8px;
}
.r-tick.t4 {
  left: 31px;
  bottom: 0;
  width: 1px;
  height: 8px;
}

.world-marker {
  position: absolute;
  z-index: 20;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  transform: translate(-50%, -50%);
  pointer-events: none;
  transition: opacity 0.2s ease;
}

.world-marker i {
  display: block;
  width: 15px;
  height: 15px;
  border: 1px solid var(--cyan);
  transform: rotate(45deg);
  box-shadow: 0 0 10px rgba(112, 231, 255, 0.4);
}

.world-marker span {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.16em;
  padding: 3px 5px;
  background: rgba(4, 9, 19, 0.62);
  white-space: nowrap;
}

.objective-marker i {
  width: 21px;
  height: 21px;
  border-color: var(--gold);
  box-shadow: 0 0 18px rgba(255, 207, 92, 0.55);
  animation: markerSpin 5s linear infinite;
}

@keyframes markerSpin {
  to {
    transform: rotate(405deg);
  }
}

.web-target {
  z-index: 21;
}

.web-target i {
  width: 29px;
  height: 29px;
  border-color: var(--green);
  border-radius: 50%;
  transform: none;
  box-shadow: 0 0 17px rgba(124, 255, 101, 0.6), inset 0 0 8px rgba(124, 255, 101, 0.2);
  animation: webTargetPulse 0.7s ease-in-out infinite alternate;
}

@keyframes webTargetPulse {
  to {
    transform: scale(1.3);
    opacity: 0.5;
  }
}

.civilian-marker i {
  border-color: var(--cyan);
  border-radius: 50%;
  transform: none;
  box-shadow: 0 0 18px rgba(112, 231, 255, 0.6);
}

.prompt {
  position: absolute;
  left: 50%;
  bottom: 26px;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 8px 15px;
  background: rgba(4, 9, 19, 0.72);
  border: 1px solid rgba(209, 235, 255, 0.16);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.16em;
  color: var(--muted);
  transition: opacity 0.2s ease;
  backdrop-filter: blur(7px);
}

.prompt.is-hidden {
  opacity: 0;
  visibility: hidden;
}

.prompt kbd {
  font: 700 10px var(--font-ui);
  letter-spacing: 0.12em;
  color: var(--ink);
  background: var(--web);
  padding: 4px 7px 3px;
  border-radius: 2px;
  box-shadow: 0 0 12px rgba(216, 236, 255, 0.3);
}

.toast-stack {
  position: absolute;
  right: 36px;
  top: 31%;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 6px;
}

.toast {
  padding: 6px 10px;
  font-family: var(--font-display);
  font-size: 18px;
  letter-spacing: 0.06em;
  background: rgba(4, 9, 19, 0.7);
  border-right: 2px solid var(--cyan);
  animation: toastIn 0.28s ease both, toastOut 0.35s ease 1.35s both;
  text-shadow: 0 0 12px rgba(112, 231, 255, 0.25);
}

.toast.is-score {
  border-color: var(--gold);
  color: var(--gold);
}
.toast.is-green {
  border-color: var(--green);
  color: #caffbc;
}
.toast.is-red {
  border-color: var(--red);
  color: #ffb4bc;
}

@keyframes toastIn {
  from {
    opacity: 0;
    transform: translateX(20px);
  }
}

@keyframes toastOut {
  to {
    opacity: 0;
    transform: translateX(8px);
  }
}

.boss-banner {
  position: absolute;
  top: 28%;
  left: 50%;
  transform: translateX(-50%);
  text-align: center;
  padding: 15px 38px 12px;
  background: linear-gradient(90deg, transparent, rgba(8, 18, 9, 0.85) 15%, rgba(8, 18, 9, 0.85) 85%, transparent);
  border-top: 1px solid rgba(124, 255, 101, 0.55);
  border-bottom: 1px solid rgba(124, 255, 101, 0.35);
  animation: bannerIn 0.6s ease both;
}

.boss-banner span {
  display: block;
  font-size: 10px;
  letter-spacing: 0.3em;
  color: var(--green);
  font-weight: 700;
}

.boss-banner strong {
  display: block;
  margin-top: 4px;
  font-family: var(--font-display);
  font-size: clamp(24px, 3vw, 38px);
  letter-spacing: 0.1em;
  font-weight: 500;
}

@keyframes bannerIn {
  from {
    opacity: 0;
    letter-spacing: 0.3em;
    transform: translateX(-50%) scale(1.04);
  }
}

/* ---------------- Touch ---------------- */

.touch-controls {
  display: none;
  pointer-events: none;
}

/* ---------------- Title ---------------- */

.title-screen {
  position: absolute;
  inset: 0;
  z-index: 30;
  padding: var(--safe-top) clamp(22px, 5vw, 80px) var(--safe-bottom);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  background:
    linear-gradient(90deg, rgba(3, 7, 16, 0.88) 0%, rgba(3, 7, 16, 0.57) 38%, transparent 68%),
    linear-gradient(180deg, rgba(3, 7, 16, 0.46), transparent 25%, transparent 73%, rgba(3, 7, 16, 0.88));
  transition: opacity 0.55s ease, visibility 0.55s ease;
}

.title-top,
.title-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  max-width: 1540px;
  width: 100%;
  margin: 0 auto;
}

.fan-tag,
.platform-tag {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.24em;
  color: rgba(239, 245, 255, 0.58);
}

.fan-tag {
  display: flex;
  align-items: center;
  gap: 10px;
}

.fan-tag::before {
  content: "";
  width: 26px;
  height: 1px;
  background: var(--red);
}

.title-lockup {
  width: min(590px, 48vw);
  margin-top: auto;
  margin-bottom: 6vh;
  animation: titleUp 0.9s cubic-bezier(0.2, 0.7, 0.2, 1) both;
}

@keyframes titleUp {
  from {
    opacity: 0;
    transform: translateY(30px);
  }
}

.title-kicker {
  display: flex;
  align-items: center;
  gap: 10px;
  color: #c9d9ee;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.25em;
}

.title-kicker span {
  width: 32px;
  height: 2px;
  background: var(--red);
  box-shadow: 0 0 12px var(--red);
}

.title-lockup h1 {
  margin: 16px 0 12px;
  line-height: 0.8;
  font-family: var(--font-display);
  font-weight: 700;
  letter-spacing: -0.035em;
  text-transform: uppercase;
}

.spider-word {
  display: block;
  font-size: clamp(24px, 2.4vw, 34px);
  letter-spacing: 0.23em;
  color: var(--white);
  margin-left: 4px;
  text-shadow: 0 0 30px rgba(244, 247, 255, 0.22);
}

.neon-word {
  display: block;
  position: relative;
  font-size: clamp(82px, 9vw, 148px);
  line-height: 0.8;
  color: var(--red);
  text-shadow: 5px 5px 0 rgba(44, 109, 255, 0.65), 0 0 60px rgba(255, 41, 72, 0.3);
}

.neon-word span {
  display: block;
  font-size: 0.67em;
  color: var(--white);
  letter-spacing: 0.02em;
  margin-left: 0.3em;
  text-shadow: 4px 4px 0 rgba(255, 41, 72, 0.62), 0 0 50px rgba(44, 109, 255, 0.3);
}

.one-liner {
  margin: 18px 0 0;
  font-family: var(--font-display);
  font-size: clamp(18px, 1.8vw, 26px);
  letter-spacing: 0.2em;
  color: var(--cyan);
}

.title-copy {
  max-width: 430px;
  margin: 11px 0 0;
  color: #b6c6dc;
  font-size: 13px;
  line-height: 1.55;
}

.title-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 11px;
  margin-top: 24px;
}

.primary-btn,
.ghost-btn {
  pointer-events: auto;
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 18px;
  min-height: 52px;
  padding: 0 23px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.18em;
  transition: transform 0.18s ease, background 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease;
}

.primary-btn {
  min-width: 210px;
  background: var(--red);
  color: var(--white);
  clip-path: polygon(0 0, 100% 0, 94% 100%, 0 100%);
  box-shadow: 0 10px 36px rgba(255, 41, 72, 0.24);
}

.primary-btn::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(115deg, transparent 35%, rgba(255, 255, 255, 0.18) 50%, transparent 65%);
  transform: translateX(-100%);
  transition: transform 0.5s ease;
}

.primary-btn:hover {
  background: var(--red-hot);
  transform: translateY(-2px);
  box-shadow: 0 14px 44px rgba(255, 41, 72, 0.34);
}

.primary-btn:hover::before {
  transform: translateX(100%);
}

.primary-btn i {
  font-size: 13px;
  font-style: normal;
}

.ghost-btn {
  border: 1px solid rgba(218, 235, 255, 0.25);
  background: rgba(5, 10, 22, 0.38);
  color: #dce9f8;
  clip-path: polygon(0 0, 100% 0, 96% 100%, 0 100%);
}

.ghost-btn:hover {
  border-color: var(--cyan);
  background: rgba(15, 36, 58, 0.62);
  transform: translateY(-2px);
}

.title-footer {
  align-items: flex-end;
}

.title-meta {
  display: flex;
  align-items: center;
  gap: 9px;
  color: #8fa2bc;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.18em;
}

.title-meta span {
  color: var(--white);
  font-family: var(--font-display);
  font-size: 18px;
  letter-spacing: 0;
}

.title-meta b {
  width: 1px;
  height: 14px;
  background: rgba(255, 255, 255, 0.2);
  margin: 0 4px;
}

.icon-btn {
  background: none;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.18em;
  color: #8fa2bc;
  padding: 8px 0;
}

.icon-btn:hover {
  color: var(--white);
}

/* ---------------- Modal ---------------- */

.modal-layer {
  position: absolute;
  inset: 0;
  z-index: 80;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: rgba(2, 5, 12, 0.72);
  backdrop-filter: blur(13px);
  transition: opacity 0.25s ease;
}

.modal-card {
  position: relative;
  width: min(680px, 94vw);
  max-height: 88vh;
  overflow: auto;
  padding: clamp(26px, 4vw, 48px);
  background:
    linear-gradient(135deg, rgba(255, 41, 72, 0.1), transparent 35%),
    rgba(8, 14, 28, 0.96);
  border: 1px solid rgba(183, 216, 255, 0.18);
  box-shadow: 0 30px 100px rgba(0, 0, 0, 0.65);
  clip-path: polygon(0 0, 100% 0, 100% 94%, 96% 100%, 0 100%);
}

.modal-card h2 {
  margin: 8px 0 20px;
  font-family: var(--font-display);
  font-size: clamp(38px, 5vw, 60px);
  line-height: 0.9;
  letter-spacing: 0.02em;
}

.close-btn {
  position: absolute;
  right: 18px;
  top: 14px;
  width: 34px;
  height: 34px;
  background: none;
  color: var(--muted);
  font-size: 26px;
  font-weight: 300;
}

.close-btn:hover {
  color: var(--white);
}

.modal-content {
  display: grid;
  gap: 18px;
}

.control-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px 22px;
}

.control-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 9px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  font-size: 12px;
  color: #c4d3e6;
}

.control-item kbd {
  font: 700 10px var(--font-ui);
  letter-spacing: 0.08em;
  padding: 5px 8px;
  background: rgba(220, 240, 255, 0.1);
  border: 1px solid rgba(220, 240, 255, 0.18);
  color: var(--white);
  white-space: nowrap;
}

.manual-note {
  padding-left: 12px;
  border-left: 2px solid var(--red);
  font-size: 12px;
  line-height: 1.65;
  color: #9fb1c8;
}

.manual-note strong {
  color: var(--white);
}

/* ---------------- Cutscene ---------------- */

.cutscene-overlay {
  position: absolute;
  inset: 0;
  z-index: 45;
  pointer-events: none;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 11vh clamp(24px, 7vw, 110px) 11vh;
  transition: opacity 0.35s ease;
}

.cutscene-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

#cutsceneChapter {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.3em;
  color: rgba(239, 247, 255, 0.6);
}

.skip-btn {
  pointer-events: auto;
  background: rgba(5, 10, 22, 0.34);
  border: 1px solid rgba(255, 255, 255, 0.16);
  padding: 7px 12px;
  color: rgba(239, 247, 255, 0.7);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.18em;
}

.skip-btn:hover {
  color: var(--white);
  border-color: var(--cyan);
}

.cutscene-caption {
  max-width: 760px;
  animation: captionIn 0.5s ease both;
}

@keyframes captionIn {
  from {
    opacity: 0;
    transform: translateY(14px);
  }
}

.caption-rule {
  display: block;
  width: 55px;
  height: 2px;
  background: var(--red);
  box-shadow: 0 0 13px rgba(255, 41, 72, 0.6);
  margin-bottom: 16px;
}

.cutscene-caption p {
  margin: 0;
  max-width: 720px;
  font-family: var(--font-display);
  font-size: clamp(32px, 4.7vw, 64px);
  line-height: 0.95;
  letter-spacing: 0.015em;
  text-transform: uppercase;
  text-shadow: 0 4px 26px rgba(0, 0, 0, 0.65);
}

/* ---------------- Panels ---------------- */

.panel-screen {
  position: absolute;
  inset: 0;
  z-index: 60;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: max(24px, var(--safe-top)) 24px max(24px, var(--safe-bottom));
  transition: opacity 0.35s ease, visibility 0.35s ease;
}

.panel-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 20% 40%, rgba(255, 41, 72, 0.16), transparent 45%),
    radial-gradient(ellipse at 82% 72%, rgba(44, 109, 255, 0.15), transparent 44%),
    rgba(2, 5, 12, 0.78);
  backdrop-filter: blur(12px);
}

.result-card,
.upgrade-wrap {
  position: relative;
  z-index: 2;
  width: min(650px, 94vw);
  padding: clamp(26px, 4vw, 52px);
  background:
    linear-gradient(120deg, rgba(255, 41, 72, 0.09), transparent 35%),
    rgba(8, 14, 28, 0.92);
  border: 1px solid rgba(191, 221, 255, 0.18);
  box-shadow: 0 34px 110px rgba(0, 0, 0, 0.64);
  clip-path: polygon(0 0, 100% 0, 100% 93%, 95% 100%, 0 100%);
}

.result-card h2,
.upgrade-wrap h2 {
  margin: 8px 0 12px;
  font-family: var(--font-display);
  font-size: clamp(44px, 6vw, 78px);
  line-height: 0.83;
  letter-spacing: 0.01em;
  font-weight: 600;
}

.result-card h2 em {
  color: var(--red);
  font-style: normal;
  text-shadow: 3px 3px 0 rgba(44, 109, 255, 0.48);
}

.result-card > p,
.upgrade-wrap > p {
  margin: 0 0 23px;
  max-width: 430px;
  color: #aabdd5;
  font-size: 13px;
  line-height: 1.55;
}

.result-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1px;
  margin: 20px 0 27px;
  background: rgba(255, 255, 255, 0.09);
}

.result-grid div {
  padding: 14px 12px;
  background: rgba(6, 11, 23, 0.83);
}

.result-grid span {
  display: block;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.17em;
  color: #8094ae;
  margin-bottom: 5px;
}

.result-grid strong {
  font-family: var(--font-display);
  font-size: 26px;
  font-weight: 600;
  letter-spacing: 0.04em;
  font-variant-numeric: tabular-nums;
}

.fail-card .eyebrow {
  color: var(--red-hot);
}

.fail-card h2 em {
  color: var(--red);
}

.fail-lives {
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 12px 0;
  margin-bottom: 18px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.fail-lives span {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.19em;
  color: var(--muted);
}

.fail-card .ghost-btn {
  margin-left: 8px;
}

.victory-bg {
  background:
    radial-gradient(ellipse at 75% 20%, rgba(255, 176, 92, 0.22), transparent 40%),
    radial-gradient(ellipse at 18% 80%, rgba(44, 109, 255, 0.16), transparent 42%),
    rgba(3, 7, 15, 0.72);
}

.victory-card h2 em {
  color: var(--gold);
  text-shadow: 3px 3px 0 rgba(255, 41, 72, 0.42);
}

.upgrade-wrap {
  width: min(1040px, 94vw);
}

.upgrade-cards {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  margin-top: 22px;
}

.upgrade-card {
  pointer-events: auto;
  position: relative;
  min-height: 225px;
  padding: 23px 20px;
  text-align: left;
  background:
    linear-gradient(155deg, rgba(112, 231, 255, 0.1), transparent 45%),
    rgba(8, 16, 32, 0.86);
  border: 1px solid rgba(178, 217, 255, 0.18);
  clip-path: polygon(0 0, 100% 0, 100% 92%, 92% 100%, 0 100%);
  transition: transform 0.2s ease, border-color 0.2s ease, background 0.2s ease;
}

.upgrade-card:hover {
  transform: translateY(-5px);
  border-color: var(--cyan);
  background:
    linear-gradient(155deg, rgba(112, 231, 255, 0.2), transparent 48%),
    rgba(10, 23, 43, 0.92);
}

.upgrade-card .up-grade {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: var(--cyan);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.18em;
}

.upgrade-card .up-icon {
  display: block;
  font-size: 30px;
  line-height: 1;
  color: var(--red-hot);
  margin: 27px 0 12px;
  text-shadow: 0 0 24px rgba(255, 41, 72, 0.25);
}

.upgrade-card h3 {
  margin: 0 0 7px;
  font-family: var(--font-display);
  font-size: 25px;
  font-weight: 600;
  letter-spacing: 0.04em;
}

.upgrade-card p {
  margin: 0;
  color: #91a6bf;
  font-size: 11px;
  line-height: 1.55;
}

.upgrade-card::after {
  content: "SELECT";
  position: absolute;
  right: 16px;
  bottom: 15px;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.18em;
  color: rgba(112, 231, 255, 0.5);
}

.pause-card {
  width: min(450px, 92vw);
  text-align: center;
}

.pause-card h2 {
  margin-bottom: 24px;
}

.pause-actions {
  display: grid;
  gap: 10px;
}

.pause-actions .primary-btn,
.pause-actions .ghost-btn {
  width: 100%;
}

.pause-tip {
  margin: 22px 0 0;
  font-size: 10px;
  line-height: 1.6;
  letter-spacing: 0.06em;
  color: #7f93ad;
}

/* ---------------- Loading ---------------- */

.loading {
  position: absolute;
  inset: 0;
  z-index: 100;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 18px;
  background: #050914;
  transition: opacity 0.55s ease, visibility 0.55s ease;
}

.loading span {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.28em;
  color: #8498b2;
}

.loading-mark {
  position: relative;
  width: 46px;
  height: 46px;
  animation: loadSpin 3.5s linear infinite;
}

.loading-mark i {
  position: absolute;
  inset: 0;
  border: 1px solid var(--red);
  border-radius: 0 50% 50% 50%;
  transform: rotate(45deg);
}

.loading-mark i:last-child {
  inset: 9px;
  border-color: var(--cyan);
  border-radius: 50%;
  transform: none;
}

@keyframes loadSpin {
  to {
    transform: rotate(360deg);
  }
}

.loading-bar {
  width: 150px;
  height: 2px;
  background: rgba(255, 255, 255, 0.12);
  overflow: hidden;
}

.loading-bar i {
  display: block;
  width: 45%;
  height: 100%;
  background: var(--red);
  animation: loadBar 1.1s ease-in-out infinite;
}

@keyframes loadBar {
  0% {
    transform: translateX(-120%);
  }
  100% {
    transform: translateX(340%);
  }
}

/* ---------------- Responsive ---------------- */

@media (max-width: 900px) {
  .hud {
    padding-left: 18px;
    padding-right: 18px;
  }

  .mission-card {
    min-width: 0;
    max-width: 52vw;
    padding-left: 12px;
  }

  .score-card strong {
    font-size: 24px;
  }

  .chase-clock {
    min-width: 110px;
    padding-left: 10px;
    padding-right: 10px;
  }

  .chase-clock strong {
    font-size: 28px;
  }

  .status-rail {
    left: 18px;
    width: 210px;
  }

  .goblin-panel {
    width: 52vw;
  }

  .combo-stack {
    left: 20px;
  }

  .title-lockup {
    width: min(580px, 74vw);
  }
}

@media (max-width: 640px) {
  .title-screen {
    padding-left: 22px;
    padding-right: 22px;
    background:
      linear-gradient(180deg, rgba(3, 7, 16, 0.36) 0%, rgba(3, 7, 16, 0.06) 22%, rgba(3, 7, 16, 0.74) 62%, rgba(3, 7, 16, 0.96) 100%);
  }

  .title-top {
    align-items: flex-start;
  }

  .platform-tag {
    display: none;
  }

  .title-lockup {
    width: 100%;
    margin-bottom: 1vh;
  }

  .spider-word {
    font-size: 20px;
  }

  .neon-word {
    font-size: clamp(64px, 18vw, 104px);
  }

  .one-liner {
    margin-top: 12px;
    font-size: 17px;
  }

  .title-copy {
    display: none;
  }

  .title-actions {
    margin-top: 16px;
  }

  .primary-btn {
    min-width: 188px;
    min-height: 48px;
  }

  .title-footer {
    display: none;
  }

  .hud {
    padding: 10px 12px calc(10px + env(safe-area-inset-bottom));
  }

  .hud-top {
    grid-template-columns: 1fr auto;
    gap: 8px;
  }

  .mission-card {
    max-width: 62vw;
    padding: 8px 8px 8px 10px;
  }

  .chapter-label {
    font-size: 8px;
  }

  .objective-row {
    font-size: 13px;
    gap: 6px;
  }

  .chase-clock {
    grid-column: 2;
    grid-row: 1;
    min-width: 92px;
    padding: 4px 6px;
  }

  .chase-clock .micro-label {
    font-size: 7px;
  }

  .chase-clock strong {
    font-size: 23px;
  }

  .score-card {
    display: none;
  }

  .status-rail {
    left: 12px;
    bottom: calc(82px + env(safe-area-inset-bottom));
    width: 164px;
    padding: 10px 12px;
  }

  .status-rail .status-title {
    font-size: 7px;
  }

  .meter {
    height: 5px;
    margin-bottom: 8px;
  }

  .lives-row {
    margin-top: 0;
    gap: 8px;
  }

  .lives-pips i {
    width: 13px;
    height: 6px;
  }

  .goblin-panel {
    top: 63px;
    width: 62vw;
    padding: 7px 9px;
  }

  .goblin-tag {
    font-size: 12px;
  }

  .goblin-note {
    display: none;
  }

  .combo-stack {
    top: 34%;
    left: 14px;
  }

  .combo-stack span {
    font-size: 48px;
  }

  .toast-stack {
    top: 24%;
    right: 12px;
  }

  .toast {
    font-size: 13px;
  }

  .prompt {
    bottom: 104px;
    font-size: 8px;
    padding: 6px 9px;
  }

  .reticle {
    opacity: 0.35;
  }

  .world-marker span {
    font-size: 7px;
  }

  .boss-banner {
    top: 21%;
    width: 92vw;
    padding-left: 10px;
    padding-right: 10px;
  }

  .boss-banner strong {
    font-size: 22px;
  }

  .result-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .result-card {
    padding: 28px 22px;
  }

  .result-card h2 {
    font-size: 55px;
  }

  .result-card > p {
    font-size: 11px;
  }

  .upgrade-wrap {
    padding: 24px 18px;
    max-height: 90vh;
    overflow: auto;
  }

  .upgrade-wrap h2 {
    font-size: 44px;
  }

  .upgrade-cards {
    grid-template-columns: 1fr;
    gap: 8px;
  }

  .upgrade-card {
    min-height: 0;
    padding: 14px 16px;
  }

  .upgrade-card .up-icon {
    display: none;
  }

  .upgrade-card h3 {
    margin-top: 6px;
    font-size: 20px;
  }

  .control-grid {
    grid-template-columns: 1fr;
    gap: 0;
  }

  .modal-card {
    padding: 26px 22px;
  }

  .modal-card h2 {
    font-size: 40px;
  }

  .cutscene-overlay {
    padding: 13vh 22px;
  }

  .cutscene-caption p {
    font-size: 38px;
  }

  .cinema-bars.is-active i {
    height: 7vh;
  }

  .touch-controls {
    display: block;
    position: absolute;
    inset: 0;
    pointer-events: none;
  }

  .joystick-zone {
    position: absolute;
    left: 13px;
    bottom: calc(14px + env(safe-area-inset-bottom));
    width: 122px;
    height: 122px;
    pointer-events: auto;
  }

  .joystick-base {
    position: absolute;
    inset: 0;
    border: 1px solid rgba(216, 236, 255, 0.2);
    border-radius: 50%;
    background: radial-gradient(circle, rgba(216, 236, 255, 0.08), rgba(3, 8, 18, 0.42) 70%);
    box-shadow: inset 0 0 24px rgba(112, 231, 255, 0.08);
  }

  .joystick-base::before,
  .joystick-base::after {
    content: "";
    position: absolute;
    background: rgba(216, 236, 255, 0.13);
  }

  .joystick-base::before {
    left: 18px;
    right: 18px;
    top: 50%;
    height: 1px;
  }

  .joystick-base::after {
    top: 18px;
    bottom: 18px;
    left: 50%;
    width: 1px;
  }

  .joystick-base i {
    position: absolute;
    left: 50%;
    top: 50%;
    width: 48px;
    height: 48px;
    margin: -24px;
    border: 1px solid rgba(216, 236, 255, 0.4);
    border-radius: 50%;
    background: rgba(9, 22, 42, 0.75);
    box-shadow: 0 0 18px rgba(112, 231, 255, 0.2);
    transition: transform 0.06s linear;
  }

  .touch-actions {
    position: absolute;
    right: 13px;
    bottom: calc(13px + env(safe-area-inset-bottom));
    width: 176px;
    height: 176px;
    pointer-events: none;
  }

  .touch-btn {
    pointer-events: auto;
    position: absolute;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    width: 59px;
    height: 59px;
    padding: 0;
    border-radius: 50%;
    border: 1px solid rgba(219, 239, 255, 0.32);
    background: rgba(5, 12, 25, 0.62);
    backdrop-filter: blur(7px);
    color: var(--white);
    font-family: var(--font-display);
    font-size: 12px;
    line-height: 0.9;
    letter-spacing: 0.08em;
    box-shadow: inset 0 0 16px rgba(112, 231, 255, 0.06);
  }

  .touch-btn small {
    margin-top: 4px;
    font-family: var(--font-ui);
    font-size: 6px;
    letter-spacing: 0.13em;
    color: var(--muted);
  }

  .touch-btn:active,
  .touch-btn.is-held {
    background: rgba(255, 41, 72, 0.8);
    border-color: var(--red-hot);
    transform: scale(0.95);
  }

  .touch-btn.swing {
    right: 58px;
    bottom: 58px;
    width: 72px;
    height: 72px;
    border-color: rgba(112, 231, 255, 0.5);
  }

  .touch-btn.web {
    right: 0;
    bottom: 86px;
    border-color: rgba(124, 255, 101, 0.45);
  }

  .touch-btn.strike {
    right: 2px;
    bottom: 12px;
  }

  .touch-btn.dodge {
    right: 124px;
    bottom: 0;
  }

  .touch-btn.rescue {
    display: none;
  }
}

@media (max-height: 660px) and (min-width: 641px) {
  .title-lockup {
    margin-bottom: 2vh;
  }

  .title-copy {
    display: none;
  }

  .neon-word {
    font-size: clamp(70px, 8vw, 110px);
  }

  .status-rail {
    padding-top: 10px;
    padding-bottom: 9px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
  }
}

// Fully procedural audio: a driving synth-orchestral chase score and comic-book SFX.
export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.musicGain = null;
    this.sfxGain = null;
    this.muted = false;
    this.started = false;
    this.intensity = 1;
    this.step = 0;
    this.nextNoteTime = 0;
    this.timer = null;
    this.noiseBuffer = null;
    this.chaseActive = false;
    this.bossActive = false;
  }

  async unlock() {
    if (!this.ctx) {
      const AudioContext = window.AudioContext || window.webkitAudioContext;
      if (!AudioContext) return;
      this.ctx = new AudioContext();
      this.master = this.ctx.createGain();
      this.master.gain.value = this.muted ? 0 : 0.75;
      this.master.connect(this.ctx.destination);

      const compressor = this.ctx.createDynamicsCompressor();
      compressor.threshold.value = -16;
      compressor.knee.value = 18;
      compressor.ratio.value = 4;
      compressor.attack.value = 0.003;
      compressor.release.value = 0.24;
      compressor.connect(this.master);

      this.musicGain = this.ctx.createGain();
      this.musicGain.gain.value = 0.33;
      this.musicGain.connect(compressor);

      this.sfxGain = this.ctx.createGain();
      this.sfxGain.gain.value = 0.7;
      this.sfxGain.connect(compressor);

      this.noiseBuffer = this.createNoiseBuffer();
    }
    if (this.ctx.state === 'suspended') await this.ctx.resume();
    if (!this.started) {
      this.started = true;
      this.startScheduler();
    }
  }

  createNoiseBuffer() {
    const length = this.ctx.sampleRate * 1.2;
    const buffer = this.ctx.createBuffer(1, length, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < length; i++) data[i] = Math.random() * 2 - 1;
    return buffer;
  }

  setMuted(value) {
    this.muted = value;
    if (this.master && this.ctx) {
      this.master.gain.setTargetAtTime(value ? 0 : 0.75, this.ctx.currentTime, 0.04);
    }
  }

  setScene({ chase = false, boss = false, calm = false } = {}) {
    this.chaseActive = chase;
    this.bossActive = boss;
    this.intensity = calm ? 0.55 : boss ? 1.35 : chase ? 1.12 : 0.85;
    if (this.musicGain && this.ctx) {
      this.musicGain.gain.setTargetAtTime(calm ? 0.2 : 0.31, this.ctx.currentTime, 0.4);
    }
  }

  startScheduler() {
    if (!this.ctx) return;
    this.nextNoteTime = this.ctx.currentTime + 0.08;
    this.timer = window.setInterval(() => this.schedule(), 25);
  }

  schedule() {
    if (!this.ctx || this.muted) return;
    const tempo = this.bossActive ? 142 : this.chaseActive ? 130 : 104;
    const stepDur = 60 / tempo / 4;
    while (this.nextNoteTime < this.ctx.currentTime + 0.12) {
      this.playStep(this.step, this.nextNoteTime, stepDur, tempo);
      this.nextNoteTime += stepDur;
      this.step = (this.step + 1) % 64;
    }
  }

  playStep(step, time, stepDur, tempo) {
    const bar = Math.floor(step / 16) % 4;
    const beat = step % 16;
    const intensity = this.intensity;
    const roots = [49.0, 43.65, 58.27, 46.25]; // G, F, Bb, F# – dark, heroic tension
    const root = roots[bar];
    const chase = this.chaseActive;
    const boss = this.bossActive;

    // Low pulse / engine.
    if (chase || boss) {
      if (beat === 0 || beat === 6 || beat === 10 || (boss && beat === 13)) {
        this.kick(time, 0.8 * intensity);
      }
      if (beat === 4 || beat === 12) this.snare(time, 0.45 * intensity);
      if (beat % 2 === 0) this.hat(time, 0.12 * intensity, beat % 4 === 0 ? 0.05 : 0.08);
    } else {
      if (beat === 0) this.kick(time, 0.35);
      if (beat === 8) this.hat(time, 0.05, 0.11);
    }

    // 16th bass engine.
    if (chase || boss) {
      const pattern = [0, 0, 12, 0, 0, 7, 0, 10, 0, 0, 12, 0, 7, 0, 10, 7];
      const semi = pattern[beat];
      this.bass(root * Math.pow(2, semi / 12), time, stepDur * 0.72, 0.16 * intensity);
    }

    // Neon arpeggio.
    if (step % 2 === 0 || boss) {
      const arp = [0, 3, 7, 10, 12, 10, 7, 3];
      const octave = bar === 2 ? 4 : 2;
      const freq = root * octave * Math.pow(2, arp[(step / 2) % 8] / 12);
      this.lead(freq, time, stepDur * (boss ? 0.8 : 1.5), 0.024 * intensity);
    }

    // Wide pad at bar changes.
    if (beat === 0 && (chase || boss || step === 0)) {
      this.pad(root * 2, root * 2 * 1.5, root * 3, time, stepDur * 15, 0.047 * intensity);
    }

    // Orchestral stabs.
    if ((chase || boss) && (beat === 0 || beat === 8)) {
      this.brass(root * 4, time, stepDur * 3, 0.035 * intensity);
    }

    // Boss alarm pulse.
    if (boss && beat % 4 === 3) {
      this.lead(root * 8, time, stepDur * 0.45, 0.019, 'sawtooth');
    }
  }

  tone({ freq, endFreq, time, dur, type = 'sine', gain = 0.1, destination = this.musicGain, attack = 0.01, release = 0.05 }) {
    if (!this.ctx || !destination) return;
    const osc = this.ctx.createOscillator();
    const amp = this.ctx.createGain();
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 2800;
    filter.Q.value = 0.8;
    osc.type = type;
    osc.frequency.setValueAtTime(freq, time);
    if (endFreq) osc.frequency.exponentialRampToValueAtTime(Math.max(20, endFreq), time + dur);
    amp.gain.setValueAtTime(0.0001, time);
    amp.gain.exponentialRampToValueAtTime(gain, time + attack);
    amp.gain.exponentialRampToValueAtTime(0.0001, time + dur + release);
    osc.connect(filter);
    filter.connect(amp);
    amp.connect(destination);
    osc.start(time);
    osc.stop(time + dur + release + 0.03);
  }

  kick(time, gain = 0.7) {
    this.tone({ freq: 160, endFreq: 39, time, dur: 0.22, type: 'sine', gain, destination: this.musicGain, attack: 0.002, release: 0.08 });
  }

  snare(time, gain = 0.4) {
    if (!this.ctx || !this.noiseBuffer) return;
    const source = this.ctx.createBufferSource();
    source.buffer = this.noiseBuffer;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.value = 1800;
    filter.Q.value = 0.7;
    const amp = this.ctx.createGain();
    amp.gain.setValueAtTime(gain, time);
    amp.gain.exponentialRampToValueAtTime(0.0001, time + 0.18);
    source.connect(filter);
    filter.connect(amp);
    amp.connect(this.musicGain);
    source.start(time, Math.random() * 0.2, 0.2);
  }

  hat(time, gain = 0.1, decay = 0.04) {
    if (!this.ctx || !this.noiseBuffer) return;
    const source = this.ctx.createBufferSource();
    source.buffer = this.noiseBuffer;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'highpass';
    filter.frequency.value = 7000;
    const amp = this.ctx.createGain();
    amp.gain.setValueAtTime(gain, time);
    amp.gain.exponentialRampToValueAtTime(0.0001, time + decay);
    source.connect(filter);
    filter.connect(amp);
    amp.connect(this.musicGain);
    source.start(time, Math.random() * 0.3, decay + 0.02);
  }

  bass(freq, time, dur, gain) {
    const osc = this.ctx.createOscillator();
    const amp = this.ctx.createGain();
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(900, time);
    filter.frequency.exponentialRampToValueAtTime(180, time + dur);
    filter.Q.value = 5;
    osc.type = 'sawtooth';
    osc.frequency.value = freq;
    amp.gain.setValueAtTime(0.0001, time);
    amp.gain.exponentialRampToValueAtTime(gain, time + 0.012);
    amp.gain.exponentialRampToValueAtTime(0.0001, time + dur);
    osc.connect(filter);
    filter.connect(amp);
    amp.connect(this.musicGain);
    osc.start(time);
    osc.stop(time + dur + 0.04);
  }

  lead(freq, time, dur, gain, type = 'triangle') {
    this.tone({ freq, time, dur, type, gain, destination: this.musicGain, attack: 0.005, release: 0.06 });
  }

  pad(f1, f2, f3, time, dur, gain) {
    [f1, f2, f3].forEach((freq, i) => {
      this.tone({
        freq,
        time,
        dur,
        type: i === 1 ? 'sawtooth' : 'triangle',
        gain,
        destination: this.musicGain,
        attack: 0.4,
        release: 0.6,
      });
    });
  }

  brass(freq, time, dur, gain) {
    this.tone({ freq, endFreq: freq * 0.985, time, dur, type: 'sawtooth', gain, destination: this.musicGain, attack: 0.025, release: 0.12 });
  }

  // ---------------- SFX ----------------

  sfx(name, volume = 1) {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime;
    switch (name) {
      case 'ui':
        this.tone({ freq: 660, endFreq: 880, time: t, dur: 0.06, type: 'triangle', gain: 0.08, destination: this.sfxGain, release: 0.03 });
        break;
      case 'thwip':
        this.noiseHit(t, 0.15, 0.28, 4300, 'highpass', volume);
        this.tone({ freq: 920, endFreq: 160, time: t, dur: 0.12, type: 'square', gain: 0.055 * volume, destination: this.sfxGain, release: 0.02 });
        break;
      case 'swing':
        this.whoosh(t, 0.5, 0.2, volume);
        break;
      case 'jump':
        this.tone({ freq: 190, endFreq: 360, time: t, dur: 0.16, type: 'triangle', gain: 0.08 * volume, destination: this.sfxGain, release: 0.03 });
        break;
      case 'land':
        this.noiseHit(t, 0.25, 0.14, 560, 'lowpass', volume, 0.13);
        break;
      case 'webhit':
        this.noiseHit(t, 0.28, 0.12, 2800, 'bandpass', volume, 0.14);
        this.tone({ freq: 300, endFreq: 120, time: t, dur: 0.16, type: 'square', gain: 0.05 * volume, destination: this.sfxGain });
        break;
      case 'strike':
        this.noiseHit(t, 0.35, 0.2, 700, 'lowpass', volume, 0.15);
        this.tone({ freq: 120, endFreq: 62, time: t, dur: 0.35, type: 'sine', gain: 0.17 * volume, destination: this.sfxGain, release: 0.12 });
        break;
      case 'explode':
        this.noiseHit(t, 0.6, 0.5, 720, 'lowpass', volume, 0.35);
        this.tone({ freq: 95, endFreq: 32, time: t, dur: 0.7, type: 'sine', gain: 0.2 * volume, destination: this.sfxGain, release: 0.2 });
        break;
      case 'rescue':
        [523, 659, 784, 1046].forEach((f, i) => {
          this.tone({ freq: f, time: t + i * 0.06, dur: 0.18, type: 'triangle', gain: 0.07 * volume, destination: this.sfxGain, release: 0.1 });
        });
        break;
      case 'damage':
        this.noiseHit(t, 0.28, 0.18, 420, 'lowpass', volume, 0.18);
        this.tone({ freq: 160, endFreq: 80, time: t, dur: 0.3, type: 'sawtooth', gain: 0.06 * volume, destination: this.sfxGain });
        break;
      case 'laugh':
        this.goblinLaugh(t, volume);
        break;
      case 'win':
        [392, 523, 659, 784].forEach((f, i) => {
          this.tone({ freq: f, time: t + i * 0.11, dur: 0.5, type: 'triangle', gain: 0.075 * volume, destination: this.sfxGain, release: 0.2 });
        });
        break;
      case 'fail':
        [330, 277, 220, 164].forEach((f, i) => {
          this.tone({ freq: f, time: t + i * 0.13, dur: 0.4, type: 'sawtooth', gain: 0.045 * volume, destination: this.sfxGain, release: 0.16 });
        });
        break;
      case 'slowmo':
        this.tone({ freq: 320, endFreq: 62, time: t, dur: 0.8, type: 'sine', gain: 0.08 * volume, destination: this.sfxGain, release: 0.25 });
        break;
      default:
        break;
    }
  }

  noiseHit(time, gain, dur, freq, type = 'lowpass', volume = 1, attack = 0.005) {
    if (!this.noiseBuffer) return;
    const source = this.ctx.createBufferSource();
    source.buffer = this.noiseBuffer;
    const filter = this.ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.value = freq;
    filter.Q.value = type === 'bandpass' ? 1.4 : 0.6;
    const amp = this.ctx.createGain();
    amp.gain.setValueAtTime(0.0001, time);
    amp.gain.exponentialRampToValueAtTime(gain * volume, time + attack);
    amp.gain.exponentialRampToValueAtTime(0.0001, time + dur);
    source.connect(filter);
    filter.connect(amp);
    amp.connect(this.sfxGain);
    source.start(time, Math.random() * 0.25, dur + 0.05);
  }

  whoosh(time, dur, gain, volume) {
    if (!this.noiseBuffer) return;
    const source = this.ctx.createBufferSource();
    source.buffer = this.noiseBuffer;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.Q.value = 1.8;
    filter.frequency.setValueAtTime(320, time);
    filter.frequency.exponentialRampToValueAtTime(1600, time + dur * 0.45);
    filter.frequency.exponentialRampToValueAtTime(240, time + dur);
    const amp = this.ctx.createGain();
    amp.gain.setValueAtTime(0.0001, time);
    amp.gain.exponentialRampToValueAtTime(gain * volume, time + 0.12);
    amp.gain.exponentialRampToValueAtTime(0.0001, time + dur);
    source.connect(filter);
    filter.connect(amp);
    amp.connect(this.sfxGain);
    source.start(time, Math.random() * 0.2, dur + 0.05);
  }

  goblinLaugh(time, volume = 1) {
    const base = 180;
    for (let i = 0; i < 6; i++) {
      this.tone({
        freq: base + (i % 2) * 60 + i * 12,
        endFreq: base * 0.72,
        time: time + i * 0.09,
        dur: 0.1,
        type: 'sawtooth',
        gain: 0.035 * volume,
        destination: this.sfxGain,
        release: 0.04,
      });
    }
  }
}

