function mulberry32(seed) {
  return function random() {
    let t = (seed += 0x6d2b79f5);
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function makeWindowTexture(seed, warm = true) {
  const random = mulberry32(seed);
  const size = 256;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#0c1320';
  ctx.fillRect(0, 0, size, size);

  // Subtle facade panel variation.
  for (let i = 0; i < 30; i++) {
    ctx.fillStyle = `rgba(70,88,120,${random() * 0.12})`;
    ctx.fillRect(0, random() * size, size, 1 + random() * 15);
  }

  const cols = 7;
  const rows = 12;
  const cellW = size / cols;
  const cellH = size / rows;
  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < cols; col++) {
      const lit = random() > 0.68;
      const warmLight = random() > 0.6;
      if (lit) {
        const palette = warmLight
          ? ['#ffdba0', '#ffb963', '#f7e6c4', '#ffcf8a']
          : ['#8ee6ff', '#79a9ff', '#adfff2', '#d6ecff'];
        ctx.fillStyle = palette[Math.floor(random() * palette.length)];
        ctx.globalAlpha = 0.48 + random() * 0.52;
      } else {
        ctx.fillStyle = random() > 0.5 ? '#111b2e' : '#0a111e';
        ctx.globalAlpha = 1;
      }
      const insetX = 5;
      const insetY = 4;
      ctx.fillRect(col * cellW + insetX, row * cellH + insetY, cellW - insetX * 2, cellH - insetY * 2);
      ctx.globalAlpha = 1;
    }
  }

  // Window frames.
  ctx.strokeStyle = 'rgba(2,6,14,0.9)';
  ctx.lineWidth = 3;
  for (let col = 0; col <= cols; col++) {
    ctx.beginPath();
    ctx.moveTo(col * cellW, 0);
    ctx.lineTo(col * cellW, size);
    ctx.stroke();
  }
  for (let row = 0; row <= rows; row++) {
    ctx.beginPath();
    ctx.moveTo(0, row * cellH);
    ctx.lineTo(size, row * cellH);
    ctx.stroke();
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.anisotropy = 4;
  return texture;
}

function makeBillboardTexture(text, accent = '#ff2948', sub = 'NEW YORK') {
  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 256;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#040810';
  ctx.fillRect(0, 0, 512, 256);
  ctx.strokeStyle = accent;
  ctx.lineWidth = 7;
  ctx.strokeRect(8, 8, 496, 240);
  ctx.fillStyle = 'rgba(255,255,255,0.05)';
  for (let i = 0; i < 20; i++) ctx.fillRect(0, i * 16, 512, 2);
  ctx.fillStyle = accent;
  ctx.font = '800 94px "Arial Narrow", Impact, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(text, 256, 115);
  ctx.fillStyle = '#d9ecff';
  ctx.font = '600 26px "Trebuchet MS", sans-serif';
  ctx.letterSpacing = '8px';
  ctx.fillText(sub, 256, 190);
  ctx.fillStyle = accent;
  ctx.fillRect(60, 221, 392, 4);
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.anisotropy = 4;
  return texture;
}

function makeGlowTexture() {
  const canvas = document.createElement('canvas');
  canvas.width = 128;
  canvas.height = 128;
  const ctx = canvas.getContext('2d');
  const grad = ctx.createRadialGradient(64, 64, 0, 64, 64, 64);
  grad.addColorStop(0, 'rgba(255,255,255,1)');
  grad.addColorStop(0.18, 'rgba(255,255,255,0.8)');
  grad.addColorStop(0.45, 'rgba(255,255,255,0.18)');
  grad.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, 128, 128);
  return new THREE.CanvasTexture(canvas);
}

export class City {
  constructor(scene, renderer) {
    this.scene = scene;
    this.renderer = renderer;
    this.buildings = [];
    this.anchors = [];
    this.cameraMeshes = [];
    this.roofs = [];
    this.cars = [];
    this.signs = [];
    this.beacons = [];
    this.moodName = 'sunset';
    this.time = 0;
    this.random = mulberry32(1987);
    this.glowTexture = makeGlowTexture();
    this.tmp = new THREE.Vector3();
    this.raycaster = new THREE.Raycaster();
    this.sky = null;
    this.sun = null;
    this.hemi = null;
    this.fill = null;
    this.fog = null;
    this.cityGroup = new THREE.Group();
    this.scene.add(this.cityGroup);

    this.buildLighting();
    this.buildSky();
    this.buildGround();
    this.buildBuildings();
    this.buildTraffic();
    this.buildChopper();
    this.setMood('sunset', true);
  }

  buildLighting() {
    this.hemi = new THREE.HemisphereLight(PALETTES.sunset.hemiSky, PALETTES.sunset.hemiGround, 1.35);
    this.scene.add(this.hemi);

    this.sun = new THREE.DirectionalLight(PALETTES.sunset.sun, PALETTES.sunset.sunIntensity);
    this.sun.position.set(-130, 180, 90);
    this.scene.add(this.sun);

    this.fill = new THREE.DirectionalLight(PALETTES.sunset.fill, 0.8);
    this.fill.position.set(110, 80, -140);
    this.scene.add(this.fill);

    this.fog = new THREE.FogExp2(PALETTES.sunset.fog, PALETTES.sunset.fogDensity);
    this.scene.fog = this.fog;

    const bounce = new THREE.PointLight('#ff3e56', 120, 90, 2);
    bounce.position.set(0, 15, 120);
    this.scene.add(bounce);
    this.bounce = bounce;
  }

  buildSky() {
    const geometry = new THREE.SphereGeometry(620, 32, 20);
    this.skyUniforms = {
      topColor: { value: new THREE.Color(PALETTES.sunset.top) },
      midColor: { value: new THREE.Color(PALETTES.sunset.mid) },
      horizonColor: { value: new THREE.Color(PALETTES.sunset.horizon) },
    };
    const material = new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      uniforms: this.skyUniforms,
      vertexShader: `
        varying vec3 vDir;
        void main() {
          vDir = normalize(position);
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        varying vec3 vDir;
        uniform vec3 topColor;
        uniform vec3 midColor;
        uniform vec3 horizonColor;
        void main() {
          float h = clamp(vDir.y * 0.5 + 0.5, 0.0, 1.0);
          vec3 low = mix(horizonColor, midColor, smoothstep(0.47, 0.62, h));
          vec3 col = mix(low, topColor, smoothstep(0.58, 0.95, h));
          float glow = pow(max(0.0, 1.0 - abs(vDir.y - 0.02) * 5.0), 3.0);
          col += horizonColor * glow * 0.12;
          gl_FragColor = vec4(col, 1.0);
        }
      `,
    });
    this.sky = new THREE.Mesh(geometry, material);
    this.sky.frustumCulled = false;
    this.scene.add(this.sky);

    // Stars.
    const count = 500;
    const positions = new Float32Array(count * 3);
    for (let i = 0; i < count; i++) {
      const theta = this.random() * Math.PI * 2;
      const phi = Math.acos(0.08 + this.random() * 0.9);
      const r = 560;
      positions[i * 3] = Math.sin(phi) * Math.cos(theta) * r;
      positions[i * 3 + 1] = Math.cos(phi) * r;
      positions[i * 3 + 2] = Math.sin(phi) * Math.sin(theta) * r;
    }
    const starGeo = new THREE.BufferGeometry();
    starGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    this.stars = new THREE.Points(
      starGeo,
      new THREE.PointsMaterial({ color: '#d3e8ff', size: 1.45, transparent: true, opacity: 0.22, sizeAttenuation: true, depthWrite: false, fog: false })
    );
    this.scene.add(this.stars);

    // Moon.
    const moon = new THREE.Mesh(
      new THREE.SphereGeometry(17, 24, 16),
      new THREE.MeshBasicMaterial({ color: '#fff4d5', fog: false })
    );
    moon.position.set(250, 280, -410);
    this.scene.add(moon);
    const moonGlow = new THREE.Sprite(
      new THREE.SpriteMaterial({ map: this.glowTexture, color: '#ffddaa', transparent: true, opacity: 0.34, depthWrite: false, blending: THREE.AdditiveBlending, fog: false })
    );
    moonGlow.scale.set(150, 150, 1);
    moonGlow.position.copy(moon.position);
    this.scene.add(moonGlow);
    this.moon = moon;
    this.moonGlow = moonGlow;

    // Wispy horizon clouds as flattened sprites.
    for (let i = 0; i < 10; i++) {
      const cloud = new THREE.Sprite(
        new THREE.SpriteMaterial({
          map: this.glowTexture,
          color: i % 3 === 0 ? '#ff9a7a' : '#879dc8',
          transparent: true,
          opacity: 0.07 + this.random() * 0.07,
          depthWrite: false,
          fog: false,
        })
      );
      const angle = this.random() * Math.PI * 2;
      cloud.position.set(Math.cos(angle) * 390, 80 + this.random() * 90, Math.sin(angle) * 390);
      cloud.scale.set(220 + this.random() * 240, 45 + this.random() * 40, 1);
      this.scene.add(cloud);
    }
  }

  buildGround() {
    const groundGeo = new THREE.PlaneGeometry(900, 900, 1, 1);
    const groundMat = new THREE.MeshStandardMaterial({ color: '#080c14', roughness: 0.95, metalness: 0.1 });
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.06;
    this.cityGroup.add(ground);

    // Central avenue.
    const avenue = new THREE.Mesh(
      new THREE.PlaneGeometry(56, 760),
      new THREE.MeshStandardMaterial({ color: '#111722', roughness: 0.82, metalness: 0.22 })
    );
    avenue.rotation.x = -Math.PI / 2;
    avenue.position.set(0, 0.01, 0);
    this.cityGroup.add(avenue);

    const lineMat = new THREE.MeshBasicMaterial({ color: '#d5be68', transparent: true, opacity: 0.56 });
    for (let z = -360; z < 360; z += 30) {
      const dash = new THREE.Mesh(new THREE.PlaneGeometry(0.5, 14), lineMat);
      dash.rotation.x = -Math.PI / 2;
      dash.position.set(-18, 0.03, z);
      this.cityGroup.add(dash);
      const dash2 = dash.clone();
      dash2.position.x = 18;
      this.cityGroup.add(dash2);
    }

    // Crosswalk stripes at intersections.
    for (let i = -3; i <= 3; i++) {
      const z = i * CITY.gridStep + CITY.gridStep / 2;
      for (let s = -20; s <= 20; s += 4) {
        const stripe = new THREE.Mesh(new THREE.PlaneGeometry(2.2, 14), new THREE.MeshBasicMaterial({ color: '#d2d9e4', transparent: true, opacity: 0.26 }));
        stripe.rotation.x = -Math.PI / 2;
        stripe.position.set(s, 0.025, z);
        this.cityGroup.add(stripe);
      }
    }

    // Cyan lane strips.
    const cyanLine = new THREE.MeshBasicMaterial({ color: '#26d9ff', transparent: true, opacity: 0.32 });
    [-24, 24].forEach((x) => {
      const strip = new THREE.Mesh(new THREE.PlaneGeometry(0.35, 700), cyanLine);
      strip.rotation.x = -Math.PI / 2;
      strip.position.set(x, 0.035, 0);
      this.cityGroup.add(strip);
    });

    // Street lamps down the avenue.
    const lampMat = new THREE.MeshBasicMaterial({ color: '#b8efff' });
    const poleMat = new THREE.MeshStandardMaterial({ color: '#1a2638', metalness: 0.7, roughness: 0.4 });
    for (let z = -330; z <= 330; z += 46) {
      for (const x of [-27, 27]) {
        const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.16, 0.22, 9, 5), poleMat);
        pole.position.set(x, 4.5, z);
        this.cityGroup.add(pole);
        const lamp = new THREE.Mesh(new THREE.SphereGeometry(0.45, 8, 6), lampMat);
        lamp.position.set(x, 9.1, z);
        this.cityGroup.add(lamp);
        const halo = new THREE.Sprite(
          new THREE.SpriteMaterial({ map: this.glowTexture, color: '#79dfff', transparent: true, opacity: 0.5, blending: THREE.AdditiveBlending, depthWrite: false })
        );
        halo.position.copy(lamp.position);
        halo.scale.set(7, 7, 1);
        this.cityGroup.add(halo);
        this.beacons.push({ mesh: halo, phase: this.random() * 8, base: 4.5, kind: 'lamp' });
      }
    }
  }

  buildBuildings() {
    const facadeTextures = [makeWindowTexture(11), makeWindowTexture(29), makeWindowTexture(53), makeWindowTexture(77)];
    const facadeCache = facadeTextures.map((tex) => tex);

    for (let i = -CITY.half; i <= CITY.half; i++) {
      for (let j = -CITY.half; j <= CITY.half; j++) {
        if (i === 0) continue; // central open avenue
        const x = i * CITY.gridStep;
        const z = j * CITY.gridStep;
        const isStart = x === CITY.start.x && z === CITY.start.z;
        const isWaypoint = x === CITY.waypoint.x && z === CITY.waypoint.z;
        if (isStart || isWaypoint) {
          this.createBuilding({
            x,
            z,
            width: 44,
            depth: 44,
            height: isStart ? CITY.start.top : CITY.waypoint.top,
            seedIndex: Math.abs(i * 7 + j) % facadeCache.length,
            textureCache: facadeCache,
            accent: isStart ? '#ff2948' : '#70e7ff',
            style: isStart ? 'start' : 'waypoint',
          });
          continue;
        }

        const distance = Math.hypot(x, z);
        const downtownBoost = Math.max(0, 1 - distance / 260);
        const height = 32 + Math.floor(this.random() * 52 + downtownBoost * 38);
        const width = 36 + this.random() * 7;
        const depth = 36 + this.random() * 7;
        const accentRoll = this.random();
        const accent = accentRoll > 0.78 ? '#ff2948' : accentRoll > 0.46 ? '#70e7ff' : accentRoll > 0.24 ? '#ffb657' : '#a97cff';
        this.createBuilding({
          x,
          z,
          width,
          depth,
          height,
          seedIndex: Math.abs(i * 11 + j * 3) % facadeCache.length,
          textureCache: facadeCache,
          accent,
          style: 'normal',
        });
      }
    }

    this.createBossTower();
    this.createBackgroundSkyline(facadeCache);
  }

  createBuilding({ x, z, width, depth, height, seedIndex, textureCache, accent, style }) {
    const group = new THREE.Group();
    group.position.set(x, 0, z);
    this.cityGroup.add(group);

    const texture = textureCache[seedIndex].clone();
    texture.needsUpdate = true;
    texture.wrapS = THREE.RepeatWrapping;
    texture.wrapT = THREE.RepeatWrapping;
    texture.repeat.set(Math.max(1, Math.round(width / 16)), Math.max(1, Math.round(height / 22)));
    const material = new THREE.MeshStandardMaterial({
      map: texture,
      emissiveMap: texture,
      emissive: new THREE.Color('#b7a58b'),
      emissiveIntensity: 0.66,
      roughness: 0.72,
      metalness: 0.24,
      color: new THREE.Color('#9aa6b8'),
    });

    const body = new THREE.Mesh(new THREE.BoxGeometry(width, height, depth), material);
    body.position.y = height / 2;
    group.add(body);
    this.cameraMeshes.push(body);

    // Setback crown on some buildings.
    let crownHeight = 0;
    if (style === 'normal' && this.random() > 0.62) {
      crownHeight = 6 + this.random() * 16;
      const crownW = width * 0.55;
      const crownD = depth * 0.55;
      const crownTex = texture.clone();
      crownTex.repeat.set(Math.max(1, Math.round(crownW / 14)), Math.max(1, Math.round(crownHeight / 18)));
      const crown = new THREE.Mesh(
        new THREE.BoxGeometry(crownW, crownHeight, crownD),
        new THREE.MeshStandardMaterial({
          map: crownTex,
          emissiveMap: crownTex,
          emissive: new THREE.Color('#b7a58b'),
          emissiveIntensity: 0.62,
          roughness: 0.7,
          metalness: 0.3,
          color: '#8b97a9',
        })
      );
      crown.position.y = height + crownHeight / 2;
      group.add(crown);
      this.cameraMeshes.push(crown);
    }

    const totalHeight = height + crownHeight;
    const roof = new THREE.Mesh(
      new THREE.BoxGeometry(width * 0.99, 0.9, depth * 0.99),
      new THREE.MeshStandardMaterial({ color: '#141c28', metalness: 0.55, roughness: 0.6 })
    );
    roof.position.y = totalHeight + 0.35;
    group.add(roof);

    // Neon roof trim.
    const trimMat = new THREE.MeshBasicMaterial({ color: accent, transparent: true, opacity: style === 'start' || style === 'waypoint' ? 0.8 : 0.27 });
    const trimY = totalHeight + 0.2;
    const horizontal = new THREE.BoxGeometry(width + 0.15, 0.11, 0.11);
    const vertical = new THREE.BoxGeometry(0.11, 0.11, depth + 0.15);
    [[0, trimY, -depth / 2], [0, trimY, depth / 2]].forEach(([tx, ty, tz]) => {
      const m = new THREE.Mesh(horizontal, trimMat);
      m.position.set(tx, ty, tz);
      group.add(m);
    });
    [[-width / 2, trimY, 0], [width / 2, trimY, 0]].forEach(([tx, ty, tz]) => {
      const m = new THREE.Mesh(vertical, trimMat);
      m.position.set(tx, ty, tz);
      group.add(m);
    });

    // Rooftop props.
    if (style !== 'waypoint' || this.random() > 0.5) {
      this.addRoofProps(group, width, depth, totalHeight, accent, style);
    }

    // Billboards on selected buildings.
    if (style === 'start') {
      this.addBillboard(group, width, depth, totalHeight, 'GOBLIN\nALERT', '#ff2948', 'CITYWIDE CURFEW', 6, -depth / 2 - 0.15, 'front');
      this.addBillboard(group, width, depth, totalHeight, 'NEON', '#70e7ff', 'PURSUIT', width / 2 + 0.15, 4, 'side');
    } else if (style === 'waypoint') {
      this.addBillboard(group, width, depth, totalHeight, 'SIGNAL', '#ffcf5c', 'ROOFTOP UPLINK', 0, depth / 2 + 0.15, 'back');
    } else if (style === 'normal' && this.random() > 0.78) {
      const labels = [
        ['OSCORP', '#92ff7b', 'TOMORROW TODAY'],
        ['NEON', '#ff2948', 'NIGHT LIFE'],
        ['BUGLE', '#ffcf5c', 'THE CITY PAPER'],
        ['24/7', '#70e7ff', 'OPEN ALL NIGHT'],
      ];
      const label = labels[Math.floor(this.random() * labels.length)];
      const onSide = this.random() > 0.5;
      if (onSide) {
        const signX = this.random() > 0.5 ? width / 2 + 0.15 : -width / 2 - 0.15;
        this.addBillboard(group, width, depth, totalHeight, label[0], label[1], label[2], signX, totalHeight * 0.55, 'side');
      } else {
        const signZ = this.random() > 0.5 ? depth / 2 + 0.15 : -depth / 2 - 0.15;
        this.addBillboard(group, width, depth, totalHeight, label[0], label[1], label[2], 0, totalHeight * 0.62, signZ > 0 ? 'back' : 'front');
      }
    }

    const building = {
      group,
      x,
      z,
      width,
      depth,
      height: totalHeight,
      bodyTop: height,
      roofY: totalHeight,
      style,
      accent,
      material,
    };
    this.buildings.push(building);
    this.roofs.push(building);

    // Web anchor points around the roof rim.
    const anchorY = totalHeight + 0.6;
    const ax = width * 0.48;
    const az = depth * 0.48;
    const points = [
      [x - ax, anchorY, z - az],
      [x + ax, anchorY, z - az],
      [x - ax, anchorY, z + az],
      [x + ax, anchorY, z + az],
      [x, anchorY, z - az],
      [x, anchorY, z + az],
      [x - ax, anchorY, z],
      [x + ax, anchorY, z],
    ];
    for (const p of points) {
      this.anchors.push({ point: new THREE.Vector3(p[0], p[1], p[2]), building });
    }

    return building;
  }

  addRoofProps(group, width, depth, top, accent, style) {
    // AC units.
    const acMat = new THREE.MeshStandardMaterial({ color: '#273346', metalness: 0.52, roughness: 0.7 });
    const count = style === 'start' ? 1 : 1 + Math.floor(this.random() * 3);
    for (let i = 0; i < count; i++) {
      const ac = new THREE.Mesh(new THREE.BoxGeometry(3.2, 1.8, 4.2), acMat);
      ac.position.set((this.random() - 0.5) * width * 0.55, top + 1.25, (this.random() - 0.5) * depth * 0.55);
      group.add(ac);
    }

    if (this.random() > 0.45) {
      const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.14, 9, 4), acMat);
      pole.position.set((this.random() - 0.5) * width * 0.6, top + 4.7, (this.random() - 0.5) * depth * 0.6);
      group.add(pole);
      const light = new THREE.Mesh(
        new THREE.SphereGeometry(0.28, 7, 5),
        new THREE.MeshBasicMaterial({ color: '#ff314d' })
      );
      light.position.copy(pole.position);
      light.position.y += 4.6;
      group.add(light);
      this.beacons.push({ mesh: light, phase: this.random() * 8, base: 0.45, kind: 'aviation' });
    }

    if (style === 'start') {
      // A recognizable rooftop billboard frame in front of the player's first pose.
      const frameMat = new THREE.MeshStandardMaterial({ color: '#182232', metalness: 0.8, roughness: 0.35 });
      const frame = new THREE.Group();
      frame.position.set(-width * 0.22, top + 3.2, -depth * 0.3);
      const postGeo = new THREE.BoxGeometry(0.4, 6.4, 0.4);
      const post1 = new THREE.Mesh(postGeo, frameMat);
      post1.position.x = -4;
      const post2 = post1.clone();
      post2.position.x = 4;
      frame.add(post1, post2);
      group.add(frame);
    }
  }

  addBillboard(group, width, depth, top, text, accent, sub, x, y, side) {
    const tex = makeBillboardTexture(text, accent, sub);
    const geo = new THREE.PlaneGeometry(14, 7);
    const mat = new THREE.MeshBasicMaterial({ map: tex, transparent: false, side: THREE.DoubleSide });
    const plane = new THREE.Mesh(geo, mat);
    if (side === 'side') {
      plane.rotation.y = Math.PI / 2;
      plane.position.set(x, Math.max(8, y + top * 0.3), 0);
    } else {
      plane.rotation.y = side === 'back' ? 0 : Math.PI;
      plane.position.set(x, Math.max(8, y + top * 0.25), side === 'back' ? depth / 2 + 0.16 : -depth / 2 - 0.16);
    }
    if (side === 'side') plane.position.z = 0;
    group.add(plane);

    const glow = new THREE.Sprite(
      new THREE.SpriteMaterial({ map: this.glowTexture, color: accent, transparent: true, opacity: 0.16, blending: THREE.AdditiveBlending, depthWrite: false })
    );
    glow.position.copy(plane.position);
    glow.scale.set(28, 17, 1);
    group.add(glow);
    this.signs.push({ mesh: plane, glow, phase: this.random() * 10, accent });
  }

  createBossTower() {
    const x = CITY.bossTower.x;
    const z = CITY.bossTower.z;
    const h = CITY.bossTower.top;
    const group = new THREE.Group();
    group.position.set(x, 0, z);
    this.cityGroup.add(group);

    const material = new THREE.MeshStandardMaterial({
      color: '#314850',
      metalness: 0.5,
      roughness: 0.45,
      emissive: new THREE.Color('#09261c'),
      emissiveIntensity: 0.5,
    });
    const tiers = [
      { w: 52, d: 52, h: h * 0.62 },
      { w: 38, d: 38, h: h * 0.3, offset: h * 0.62 },
      { w: 22, d: 22, h: h * 0.14, offset: h * 0.9 },
    ];
    for (const tier of tiers) {
      const box = new THREE.Mesh(new THREE.BoxGeometry(tier.w, tier.h, tier.d), material);
      box.position.y = (tier.offset || 0) + tier.h / 2;
      group.add(box);
      this.cameraMeshes.push(box);
    }
    // Green vertical light strips.
    for (const side of [-1, 1]) {
      const strip = new THREE.Mesh(
        new THREE.BoxGeometry(1.2, h * 0.8, 0.18),
        new THREE.MeshBasicMaterial({ color: '#7cff65', transparent: true, opacity: 0.8 })
      );
      strip.position.set(side * 24, h * 0.45, 26.2);
      group.add(strip);
    }
    const crown = new THREE.Mesh(
      new THREE.CylinderGeometry(1, 5, 34, 4),
      new THREE.MeshStandardMaterial({ color: '#1b2b2a', metalness: 0.8, roughness: 0.3, emissive: new THREE.Color('#082014'), emissiveIntensity: 0.6 })
    );
    crown.position.y = h + 10;
    group.add(crown);

    // Massive billboard facing the approach.
    const tex = makeBillboardTexture('OSCORP', '#7cff65', 'WE OWN THE NIGHT');
    const plane = new THREE.Mesh(new THREE.PlaneGeometry(38, 17), new THREE.MeshBasicMaterial({ map: tex, side: THREE.DoubleSide }));
    plane.position.set(0, h * 0.76, 27.1);
    group.add(plane);
    const glow = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.glowTexture, color: '#7cff65', transparent: true, opacity: 0.22, blending: THREE.AdditiveBlending, depthWrite: false }));
    glow.position.copy(plane.position);
    glow.scale.set(65, 38, 1);
    group.add(glow);

    const building = {
      group,
      x,
      z,
      width: 52,
      depth: 52,
      height: h,
      bodyTop: h,
      roofY: h,
      style: 'boss',
      accent: '#7cff65',
      material,
    };
    this.buildings.push(building);
    this.roofs.push(building);
    const anchorY = h + 0.6;
    for (const [ax, az] of [
      [-24, -24],
      [24, -24],
      [-24, 24],
      [24, 24],
      [0, -24],
      [0, 24],
      [-24, 0],
      [24, 0],
    ]) {
      this.anchors.push({ point: new THREE.Vector3(x + ax, anchorY, z + az), building });
    }
  }

  createBackgroundSkyline(textureCache) {
    const random = mulberry32(77);
    const mat = new THREE.MeshStandardMaterial({ color: '#0a1220', roughness: 0.8, metalness: 0.2 });
    const count = 60;
    const geo = new THREE.BoxGeometry(1, 1, 1);
    const instanced = new THREE.InstancedMesh(geo, mat, count);
    const dummy = new THREE.Object3D();
    for (let i = 0; i < count; i++) {
      const angle = random() * Math.PI * 2;
      const radius = 265 + random() * 190;
      const width = 20 + random() * 38;
      const height = 40 + random() * 150;
      dummy.position.set(Math.cos(angle) * radius, height / 2, Math.sin(angle) * radius);
      dummy.rotation.y = random() * Math.PI;
      dummy.scale.set(width, height, width);
      dummy.updateMatrix();
      instanced.setMatrixAt(i, dummy.matrix);
    }
    instanced.instanceMatrix.needsUpdate = true;
    this.cityGroup.add(instanced);
    this.background = instanced;

    // Tiny window lights on distant silhouettes.
    const positions = [];
    for (let i = 0; i < 800; i++) {
      const angle = random() * Math.PI * 2;
      const radius = 240 + random() * 200;
      positions.push(Math.cos(angle) * radius, 12 + random() * 150, Math.sin(angle) * radius);
    }
    const geoPoints = new THREE.BufferGeometry();
    geoPoints.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    this.distantLights = new THREE.Points(
      geoPoints,
      new THREE.PointsMaterial({ color: '#ffd495', size: 1.4, transparent: true, opacity: 0.45, depthWrite: false })
    );
    this.cityGroup.add(this.distantLights);
  }

  buildTraffic() {
    const bodyColors = ['#0e1522', '#1d2636', '#351523', '#101b29', '#1d1c27'];
    for (let i = 0; i < 20; i++) {
      const group = new THREE.Group();
      const body = new THREE.Mesh(
        new THREE.BoxGeometry(2.1, 0.75, 4.4),
        new THREE.MeshStandardMaterial({ color: bodyColors[i % bodyColors.length], metalness: 0.6, roughness: 0.35 })
      );
      body.position.y = 0.55;
      group.add(body);
      const roof = new THREE.Mesh(
        new THREE.BoxGeometry(1.7, 0.55, 2.15),
        new THREE.MeshStandardMaterial({ color: '#0b111b', metalness: 0.5, roughness: 0.25 })
      );
      roof.position.set(0, 1.2, -0.25);
      group.add(roof);
      const head = new THREE.Mesh(
        new THREE.BoxGeometry(1.65, 0.16, 0.12),
        new THREE.MeshBasicMaterial({ color: '#e8f7ff' })
      );
      head.position.set(0, 0.58, -2.22);
      group.add(head);
      const tail = head.clone();
      tail.material = new THREE.MeshBasicMaterial({ color: '#ff203e' });
      tail.position.z = 2.22;
      group.add(tail);
      const lane = i % 2 === 0 ? 1 : -1;
      const direction = lane === 1 ? -1 : 1;
      group.position.set(lane * (18 + (i % 3) * 3), 0.03, -340 + (i * 37) % 680);
      group.rotation.y = direction > 0 ? 0 : Math.PI;
      this.cityGroup.add(group);
      this.cars.push({ group, direction, speed: 10 + (i % 5) * 3, lane });
    }
  }

  buildChopper() {
    const chopper = new THREE.Group();
    const body = new THREE.Mesh(
      new THREE.SphereGeometry(2.2, 10, 8),
      new THREE.MeshStandardMaterial({ color: '#101c2c', metalness: 0.6, roughness: 0.4 })
    );
    body.scale.set(1, 0.7, 1.5);
    chopper.add(body);
    const tail = new THREE.Mesh(new THREE.BoxGeometry(0.35, 0.35, 4.5), new THREE.MeshStandardMaterial({ color: '#0d1827', metalness: 0.7, roughness: 0.3 }));
    tail.position.z = 3.3;
    chopper.add(tail);
    const rotor = new THREE.Mesh(
      new THREE.BoxGeometry(12, 0.08, 0.22),
      new THREE.MeshBasicMaterial({ color: '#4d698a', transparent: true, opacity: 0.6 })
    );
    rotor.position.y = 1.9;
    chopper.add(rotor);
    const searchlight = new THREE.Mesh(
      new THREE.ConeGeometry(14, 60, 18, 1, true),
      new THREE.MeshBasicMaterial({ color: '#d6edff', transparent: true, opacity: 0.055, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending })
    );
    searchlight.position.y = -29;
    searchlight.rotation.x = Math.PI;
    chopper.add(searchlight);
    const beacon = new THREE.Mesh(new THREE.SphereGeometry(0.22, 6, 5), new THREE.MeshBasicMaterial({ color: '#ff2d4b' }));
    beacon.position.set(0, 1.5, -1.8);
    chopper.add(beacon);
    chopper.position.set(58, 118, 40);
    chopper.rotation.y = -0.6;
    this.cityGroup.add(chopper);
    this.chopper = chopper;
    this.chopperRotor = rotor;
    this.chopperBeacon = beacon;
    this.chopperAngle = 0;
  }

  setMood(name, immediate = false) {
    if (!PALETTES[name]) return;
    this.moodName = name;
    const palette = PALETTES[name];
    const apply = () => {
      this.skyUniforms.topColor.value.set(palette.top);
      this.skyUniforms.midColor.value.set(palette.mid);
      this.skyUniforms.horizonColor.value.set(palette.horizon);
      this.fog.color.set(palette.fog);
      this.fog.density = palette.fogDensity;
      this.hemi.color.set(palette.hemiSky);
      this.hemi.groundColor.set(palette.hemiGround);
      this.sun.color.set(palette.sun);
      this.sun.intensity = palette.sunIntensity;
      this.fill.color.set(palette.fill);
      this.stars.material.opacity = palette.stars;
      if (this.moon) {
        this.moon.material.color.set(name === 'dawn' ? '#fff1cb' : '#e8f0ff');
        this.moonGlow.material.opacity = name === 'dawn' ? 0.18 : 0.34;
      }
      if (this.bounce) this.bounce.color.set(name === 'dawn' ? '#ffb37e' : '#ff3e56');
    };

    if (immediate) {
      apply();
      return;
    }
    const startTop = this.skyUniforms.topColor.value.clone();
    const startMid = this.skyUniforms.midColor.value.clone();
    const startHorizon = this.skyUniforms.horizonColor.value.clone();
    const startFog = this.fog.color.clone();
    const startSun = this.sun.color.clone();
    const startHemi = this.hemi.color.clone();
    const start = performance.now();
    const duration = 1800;
    const tick = () => {
      const t = Math.min(1, (performance.now() - start) / duration);
      const eased = t * t * (3 - 2 * t);
      this.skyUniforms.topColor.value.copy(startTop).lerp(new THREE.Color(palette.top), eased);
      this.skyUniforms.midColor.value.copy(startMid).lerp(new THREE.Color(palette.mid), eased);
      this.skyUniforms.horizonColor.value.copy(startHorizon).lerp(new THREE.Color(palette.horizon), eased);
      this.fog.color.copy(startFog).lerp(new THREE.Color(palette.fog), eased);
      this.sun.color.copy(startSun).lerp(new THREE.Color(palette.sun), eased);
      this.hemi.color.copy(startHemi).lerp(new THREE.Color(palette.hemiSky), eased);
      this.fog.density = THREE.MathUtils.lerp(this.fog.density, palette.fogDensity, 0.08);
      this.sun.intensity = THREE.MathUtils.lerp(this.sun.intensity, palette.sunIntensity, 0.08);
      this.stars.material.opacity = THREE.MathUtils.lerp(this.stars.material.opacity, palette.stars, 0.08);
      if (t < 1) requestAnimationFrame(tick);
    };
    tick();
  }

  update(dt, elapsed) {
    this.time += dt;
    for (const car of this.cars) {
      car.group.position.z += car.direction * car.speed * dt;
      if (car.group.position.z > 355) car.group.position.z = -355;
      if (car.group.position.z < -355) car.group.position.z = 355;
    }

    for (const beacon of this.beacons) {
      if (beacon.kind === 'aviation') {
        beacon.mesh.material.opacity = beacon.base + Math.sin(elapsed * 2.4 + beacon.phase) * 0.12;
        beacon.mesh.scale.setScalar(0.8 + Math.sin(elapsed * 2.4 + beacon.phase) * 0.15);
      } else if (beacon.mesh.material) {
        beacon.mesh.material.opacity = 0.36 + Math.sin(elapsed * 1.8 + beacon.phase) * 0.12;
      }
    }

    for (const sign of this.signs) {
      sign.glow.material.opacity = 0.12 + Math.sin(elapsed * 3 + sign.phase) * 0.06;
    }

    if (this.chopper) {
      this.chopperAngle += dt * 0.08;
      this.chopper.position.x = Math.cos(this.chopperAngle) * 105;
      this.chopper.position.z = Math.sin(this.chopperAngle) * 130 - 30;
      this.chopper.rotation.y = -this.chopperAngle + Math.PI / 2;
      this.chopper.position.y = 118 + Math.sin(elapsed * 0.6) * 2;
      this.chopperRotor.rotation.y += dt * 26;
      this.chopperBeacon.material.color.set(Math.sin(elapsed * 9) > 0 ? '#ff2d4b' : '#2a0308');
    }

    // Slight shimmer on distant lights.
    if (this.distantLights) this.distantLights.material.opacity = 0.38 + Math.sin(elapsed * 1.2) * 0.07;
  }

  getStartPosition() {
    return new THREE.Vector3(CITY.start.x, CITY.start.top + 1.15, CITY.start.z);
  }

  getWaypointPosition() {
    return new THREE.Vector3(CITY.waypoint.x, CITY.waypoint.top + 4.5, CITY.waypoint.z);
  }

  getBossPosition() {
    return new THREE.Vector3(CITY.bossTower.x, CITY.bossTower.top + 30, CITY.bossTower.z);
  }

  getSurfaceY(x, z, currentY) {
    let best = 0;
    for (const b of this.buildings) {
      if (
        Math.abs(x - b.x) <= b.width / 2 &&
        Math.abs(z - b.z) <= b.depth / 2 &&
        currentY >= b.roofY - 1.2
      ) {
        if (b.roofY > best) best = b.roofY;
      }
    }
    return best;
  }

  getRoofCandidate(routePoints, wanted, seedOffset = 0) {
    // Pick scenic rooftops near the chase route, avoiding repeats.
    const used = new Set();
    const result = [];
    let startIndex = seedOffset % Math.max(1, routePoints.length);
    for (let step = 0; step < 20 && result.length < wanted; step++) {
      const routePoint = routePoints[(startIndex + step * 3) % routePoints.length];
      let best = null;
      let bestDist = Infinity;
      for (const b of this.roofs) {
        if (b.style === 'boss' || b === CITY.start) continue;
        if (used.has(b)) continue;
        const d = Math.hypot(b.x - routePoint.x, b.z - routePoint.z);
        if (d < bestDist && d < 125) {
          bestDist = d;
          best = b;
        }
      }
      if (best) {
        used.add(best);
        result.push(new THREE.Vector3(best.x, best.roofY + 1.2, best.z));
      }
    }
    return result;
  }

  resolvePlayerCollisions(pos, prevPos, radius = 0.7) {
    let landedOn = null;
    for (const b of this.buildings) {
      const halfW = b.width / 2 + radius;
      const halfD = b.depth / 2 + radius;
      const dx = pos.x - b.x;
      const dz = pos.z - b.z;
      const insideX = Math.abs(dx) < halfW;
      const insideZ = Math.abs(dz) < halfD;
      if (!insideX || !insideZ) continue;

      const top = b.roofY;
      // Landing from above.
      if (prevPos.y >= top - 0.5 && pos.y <= top + 0.9) {
        if (pos.y < top + 0.5) {
          pos.y = top;
          landedOn = b;
          if (pos.velocityY !== undefined) {
            // handled by caller
          }
        }
        continue;
      }

      // Side collision only when below the roof.
      if (pos.y < top - 0.7) {
        const penetrationX = halfW - Math.abs(dx);
        const penetrationZ = halfD - Math.abs(dz);
        if (penetrationX < penetrationZ) {
          pos.x = b.x + Math.sign(dx || 1) * halfW;
        } else {
          pos.z = b.z + Math.sign(dz || 1) * halfD;
        }
      }
    }
    return landedOn;
  }

  raycastCamera(origin, target, maxDistance = 40) {
    this.raycaster.set(origin, target.clone().sub(origin).normalize());
    this.raycaster.far = maxDistance;
    const hits = this.raycaster.intersectObjects(this.cameraMeshes, false);
    if (hits.length) return hits[0].distance;
    return maxDistance;
  }

  getCarLights() {
    return this.cars;
  }

  dispose() {
    this.scene.remove(this.cityGroup);
    this.cityGroup.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) child.material.forEach((m) => m.dispose());
        else child.material.dispose();
      }
    });
  }
}

import * as THREE from 'three';

const TAU = Math.PI * 2;

function mat(color, opts = {}) {
  return new THREE.MeshStandardMaterial({
    color,
    roughness: opts.roughness ?? 0.58,
    metalness: opts.metalness ?? 0.15,
    emissive: opts.emissive ?? '#000000',
    emissiveIntensity: opts.emissiveIntensity ?? 0,
    flatShading: opts.flatShading ?? false,
    side: opts.side ?? THREE.FrontSide,
  });
}

function glowSprite(texture, color, scale, opacity = 0.55) {
  const sprite = new THREE.Sprite(
    new THREE.SpriteMaterial({
      map: texture,
      color,
      transparent: true,
      opacity,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    })
  );
  sprite.scale.set(scale, scale, 1);
  return sprite;
}

function makeGlowTexture() {
  const canvas = document.createElement('canvas');
  canvas.width = 128;
  canvas.height = 128;
  const ctx = canvas.getContext('2d');
  const grad = ctx.createRadialGradient(64, 64, 0, 64, 64, 64);
  grad.addColorStop(0, 'rgba(255,255,255,1)');
  grad.addColorStop(0.18, 'rgba(255,255,255,0.76)');
  grad.addColorStop(0.48, 'rgba(255,255,255,0.16)');
  grad.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, 128, 128);
  return new THREE.CanvasTexture(canvas);
}

const GLOW = makeGlowTexture();

function makeSpiderEmblem() {
  const group = new THREE.Group();
  const black = new THREE.MeshBasicMaterial({ color: '#080a0f' });
  const body = new THREE.Mesh(new THREE.SphereGeometry(0.055, 8, 6), black);
  body.scale.set(0.7, 2.15, 0.35);
  group.add(body);
  const legGeo = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(-0.03, 0.04, 0),
    new THREE.Vector3(-0.17, 0.12, 0),
    new THREE.Vector3(-0.26, 0.19, 0),
    new THREE.Vector3(-0.04, -0.05, 0),
    new THREE.Vector3(-0.2, -0.15, 0),
    new THREE.Vector3(-0.28, -0.25, 0),
    new THREE.Vector3(0.03, 0.04, 0),
    new THREE.Vector3(0.17, 0.12, 0),
    new THREE.Vector3(0.26, 0.19, 0),
    new THREE.Vector3(0.04, -0.05, 0),
    new THREE.Vector3(0.2, -0.15, 0),
    new THREE.Vector3(0.28, -0.25, 0),
  ]);
  group.add(new THREE.LineSegments(legGeo, new THREE.LineBasicMaterial({ color: '#080a0f', linewidth: 1 })));
  return group;
}

export class Hero {
  constructor(scene) {
    this.scene = scene;
    this.root = new THREE.Group();
    this.root.name = 'SpiderMan';
    this.scene.add(this.root);

    this.red = mat('#d5132f', { roughness: 0.42, metalness: 0.08, emissive: '#4c0310', emissiveIntensity: 0.25 });
    this.redDark = mat('#8e0c22', { roughness: 0.52 });
    this.blue = mat('#173dad', { roughness: 0.46, metalness: 0.14, emissive: '#05133a', emissiveIntensity: 0.32 });
    this.blueDark = mat('#0c2468', { roughness: 0.55 });
    this.black = mat('#070b13', { roughness: 0.5, metalness: 0.25 });
    this.white = mat('#eef8ff', { roughness: 0.22, metalness: 0.05, emissive: '#bcdfff', emissiveIntensity: 0.6 });
    this.redWeb = mat('#ff2d42', { roughness: 0.35, emissive: '#ff1029', emissiveIntensity: 0.5 });

    this.rig = new THREE.Group();
    this.root.add(this.rig);
    this.parts = {};
    this.time = 0;
    this.pose = {
      idle: 0,
      run: 0,
      swing: 0,
      shoot: 0,
      strike: 0,
      fall: 0,
    };

    this.buildBody();
    this.buildShadow();
    this.setPose(0, 0, false, false, 1);
  }

  addCapsule(parent, radius, length, material, x = 0, y = 0, z = 0, radial = 10) {
    const mesh = new THREE.Mesh(new THREE.CapsuleGeometry(radius, length, 5, radial), material);
    mesh.position.set(x, y, z);
    parent.add(mesh);
    return mesh;
  }

  buildBody() {
    const rig = this.rig;

    // Hips and torso.
    const pelvis = this.addCapsule(rig, 0.3, 0.22, this.blue, 0, 1.06, 0, 12);
    pelvis.scale.z = 0.82;
    this.parts.pelvis = pelvis;

    const torso = this.addCapsule(rig, 0.34, 0.42, this.red, 0, 1.53, 0, 14);
    torso.scale.set(1, 1, 0.8);
    this.parts.torso = torso;

    const abdomen = this.addCapsule(rig, 0.26, 0.22, this.red, 0, 1.29, 0.06, 12);
    abdomen.scale.set(0.9, 1, 0.7);
    this.parts.abdomen = abdomen;

    // Blue rib panels.
    for (const side of [-1, 1]) {
      const panel = this.addCapsule(rig, 0.16, 0.36, this.blue, side * 0.24, 1.55, 0.01, 8);
      panel.scale.set(0.58, 1, 0.6);
      panel.rotation.z = side * 0.22;
    }

    // Belt.
    const belt = new THREE.Mesh(new THREE.TorusGeometry(0.3, 0.035, 5, 16), this.black);
    belt.rotation.x = Math.PI / 2;
    belt.position.y = 1.16;
    belt.scale.z = 0.82;
    rig.add(belt);

    const emblem = makeSpiderEmblem();
    emblem.position.set(0, 1.57, 0.284);
    emblem.scale.setScalar(1.1);
    rig.add(emblem);

    // Head.
    this.headPivot = new THREE.Group();
    this.headPivot.position.set(0, 1.9, 0);
    rig.add(this.headPivot);
    const head = new THREE.Mesh(new THREE.SphereGeometry(0.255, 18, 14), this.red);
    head.scale.set(0.9, 1.06, 0.92);
    head.position.y = 0.18;
    this.headPivot.add(head);

    // Mask webbing: thin dark rings.
    const webMat = new THREE.MeshBasicMaterial({ color: '#5c0714', transparent: true, opacity: 0.72 });
    for (let i = 0; i < 3; i++) {
      const ring = new THREE.Mesh(new THREE.TorusGeometry(0.23 - i * 0.005, 0.004, 3, 24), webMat);
      ring.rotation.x = Math.PI / 2;
      ring.rotation.y = 0.32 + i * 0.4;
      ring.position.y = 0.18 + i * 0.045;
      ring.scale.z = 0.92;
      this.headPivot.add(ring);
    }
    const centerWeb = new THREE.Mesh(new THREE.TorusGeometry(0.24, 0.004, 3, 24, Math.PI), webMat);
    centerWeb.rotation.x = Math.PI / 2;
    centerWeb.position.y = 0.17;
    this.headPivot.add(centerWeb);

    // Eye lenses.
    for (const side of [-1, 1]) {
      const outline = new THREE.Mesh(new THREE.SphereGeometry(0.082, 12, 8), this.black);
      outline.scale.set(1.7, 0.9, 0.32);
      outline.position.set(side * 0.098, 0.215, 0.225);
      outline.rotation.y = side * 0.26;
      outline.rotation.z = side * 0.28;
      this.headPivot.add(outline);

      const eye = new THREE.Mesh(new THREE.SphereGeometry(0.07, 12, 8), this.white);
      eye.scale.set(1.68, 0.82, 0.3);
      eye.position.set(side * 0.1, 0.218, 0.241);
      eye.rotation.y = side * 0.26;
      eye.rotation.z = side * 0.3;
      this.headPivot.add(eye);
    }

    // Neck.
    const neck = this.addCapsule(rig, 0.13, 0.08, this.red, 0, 1.84, 0, 8);
    neck.scale.z = 0.8;

    // Arms.
    this.arms = {};
    for (const side of [-1, 1]) {
      const shoulder = new THREE.Group();
      shoulder.position.set(side * 0.39, 1.72, 0);
      rig.add(shoulder);
      const upper = this.addCapsule(shoulder, 0.11, 0.3, this.red, 0, -0.23, 0, 9);
      const upperBlue = this.addCapsule(shoulder, 0.112, 0.13, this.blue, 0, -0.1, 0, 9);
      upperBlue.scale.set(1.01, 0.9, 1.01);

      const elbow = new THREE.Group();
      elbow.position.set(0, -0.46, 0);
      shoulder.add(elbow);
      const lower = this.addCapsule(elbow, 0.095, 0.26, this.red, 0, -0.2, 0, 9);
      const hand = new THREE.Mesh(new THREE.SphereGeometry(0.105, 9, 7), this.redDark);
      hand.scale.set(0.72, 1.1, 0.64);
      hand.position.y = -0.4;
      elbow.add(hand);
      this.arms[side === -1 ? 'left' : 'right'] = { shoulder, elbow, hand, upper, lower };
    }

    // Legs.
    this.legs = {};
    for (const side of [-1, 1]) {
      const hip = new THREE.Group();
      hip.position.set(side * 0.18, 1.02, 0);
      rig.add(hip);
      const thigh = this.addCapsule(hip, 0.13, 0.28, this.blue, 0, -0.25, 0, 9);
      const thighPanel = this.addCapsule(hip, 0.132, 0.13, this.red, 0, -0.08, 0.015, 9);
      thighPanel.scale.set(1.01, 0.88, 1.01);

      const knee = new THREE.Group();
      knee.position.set(0, -0.51, 0);
      hip.add(knee);
      const shin = this.addCapsule(knee, 0.105, 0.29, this.blueDark, 0, -0.23, 0, 9);
      const boot = this.addCapsule(knee, 0.11, 0.16, this.red, 0, -0.46, 0.015, 9);
      const foot = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.1, 0.28), this.redDark);
      foot.position.set(0, -0.56, 0.06);
      knee.add(foot);
      this.legs[side === -1 ? 'left' : 'right'] = { hip, knee, thigh, shin, boot, foot };
    }

    // Tiny web shooters.
    for (const side of [-1, 1]) {
      const shooter = new THREE.Mesh(new THREE.TorusGeometry(0.09, 0.015, 4, 9), this.black);
      shooter.rotation.x = Math.PI / 2;
      shooter.position.set(side * 0.39, 1.33, 0);
      rig.add(shooter);
    }

    this.rig.scale.setScalar(1.03);
  }

  buildShadow() {
    const canvas = document.createElement('canvas');
    canvas.width = 128;
    canvas.height = 128;
    const ctx = canvas.getContext('2d');
    const grad = ctx.createRadialGradient(64, 64, 0, 64, 64, 64);
    grad.addColorStop(0, 'rgba(0,0,0,0.62)');
    grad.addColorStop(0.55, 'rgba(0,0,0,0.25)');
    grad.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, 128, 128);
    const tex = new THREE.CanvasTexture(canvas);
    this.shadow = new THREE.Mesh(
      new THREE.PlaneGeometry(2.4, 2.4),
      new THREE.MeshBasicMaterial({ map: tex, transparent: true, depthWrite: false, opacity: 0.55 })
    );
    this.shadow.rotation.x = -Math.PI / 2;
    this.shadow.renderOrder = 2;
    this.scene.add(this.shadow);
  }

  getHandWorld(target = new THREE.Vector3()) {
    return this.arms.right.hand.getWorldPosition(target);
  }

  setPosition(position) {
    this.root.position.copy(position);
  }

  setFacing(yaw, instant = false) {
    if (instant) this.root.rotation.y = yaw;
    else this.root.rotation.y = this.lerpAngle(this.root.rotation.y, yaw, 0.16);
  }

  lerpAngle(a, b, t) {
    let d = ((b - a + Math.PI) % TAU) - Math.PI;
    if (d < -Math.PI) d += TAU;
    return a + d * t;
  }

  update(dt, state) {
    this.time += dt;
    const { grounded, swinging, velocity, speed, shootTimer, strikeTimer, dodgeTimer, aimTarget, surfaceY } = state;

    const speedN = THREE.MathUtils.clamp(speed / 45, 0, 1);
    const target = {
      swing: swinging ? 1 : 0,
      shoot: shootTimer > 0 ? 1 : 0,
      strike: strikeTimer > 0 ? 1 : 0,
      run: grounded ? THREE.MathUtils.clamp(speed / 13, 0, 1) : 0,
      fall: !grounded && !swinging ? 1 : 0,
      idle: grounded && speed < 1 ? 1 : 0,
    };
    for (const key of Object.keys(this.pose)) {
      this.pose[key] = THREE.MathUtils.damp(this.pose[key], target[key], key === 'strike' ? 22 : 9, dt);
    }

    // Body bob and tilt.
    const t = this.time;
    const runWave = Math.sin(t * 13) * 0.5;
    const bodyBob = this.pose.idle * Math.sin(t * 2.1) * 0.012 + this.pose.run * Math.abs(runWave) * 0.05;
    this.rig.position.y = bodyBob;
    this.rig.rotation.x = -this.pose.swing * 0.19 + this.pose.fall * 0.04 + this.pose.strike * 0.1;
    this.rig.rotation.z = Math.sin(t * 1.6) * 0.008 + this.pose.swing * THREE.MathUtils.clamp(-velocity.x * 0.008, -0.2, 0.2);

    // Head looks toward target while airborne, otherwise forward.
    let headYaw = 0;
    let headPitch = 0;
    if ((swinging || !grounded) && aimTarget) {
      const local = this.root.worldToLocal(aimTarget.clone());
      headYaw = THREE.MathUtils.clamp(Math.atan2(local.x, local.z), -0.55, 0.55);
      headPitch = THREE.MathUtils.clamp(-Math.atan2(local.y - 2, Math.hypot(local.x, local.z)), -0.4, 0.35);
    }
    this.headPivot.rotation.y = THREE.MathUtils.damp(this.headPivot.rotation.y, headYaw - this.pose.strike * 0.2, 8, dt);
    this.headPivot.rotation.x = THREE.MathUtils.damp(this.headPivot.rotation.x, headPitch, 8, dt);

    // Arms.
    for (const side of [-1, 1]) {
      const arm = side === -1 ? this.arms.left : this.arms.right;
      let sx = 0;
      let sz = side * 0.1;
      let ex = 0.12;
      let ez = 0;

      if (this.pose.idle > 0.01) {
        sx += -0.04 + Math.sin(t * 1.7 + side) * 0.02;
        sz += side * 0.16;
        ex = 0.1;
      }
      if (this.pose.run > 0.01) {
        const run = Math.sin(t * 13 + (side === -1 ? 0 : Math.PI)) * 0.9 * this.pose.run;
        sx += run;
        ex = 0.5 + Math.max(0, run) * 0.6;
        sz = side * 0.15;
      }
      if (this.pose.swing > 0.01) {
        if (side === 1) {
          // Web arm reaches overhead.
          sx += -2.65 * this.pose.swing;
          sz += -0.24 * this.pose.swing;
          ex = 0.15;
        } else {
          // Free arm trails in the wind.
          sx += 1.1 * this.pose.swing;
          sz += -0.7 * this.pose.swing;
          ex = 0.7 * this.pose.swing;
        }
      }
      if (this.pose.fall > 0.01) {
        sx += -0.55 * this.pose.fall;
        sz += side * (0.7 * this.pose.fall);
        ex = 0.55;
      }
      if (this.pose.shoot > 0.01) {
        sx = THREE.MathUtils.lerp(sx, -1.48, this.pose.shoot);
        sz = THREE.MathUtils.lerp(sz, -0.08, this.pose.shoot);
        ex = THREE.MathUtils.lerp(ex, 0.08, this.pose.shoot);
      }
      if (this.pose.strike > 0.01) {
        if (side === 1) {
          sx = THREE.MathUtils.lerp(sx, -1.25, this.pose.strike);
          sz = THREE.MathUtils.lerp(sz, -0.2, this.pose.strike);
          ex = THREE.MathUtils.lerp(ex, 1.2, this.pose.strike);
        } else {
          sx = THREE.MathUtils.lerp(sx, 0.5, this.pose.strike);
          sz = THREE.MathUtils.lerp(sz, 0.5, this.pose.strike);
        }
      }

      arm.shoulder.rotation.x = THREE.MathUtils.damp(arm.shoulder.rotation.x, sx, 13, dt);
      arm.shoulder.rotation.z = THREE.MathUtils.damp(arm.shoulder.rotation.z, sz, 13, dt);
      arm.shoulder.rotation.y = THREE.MathUtils.damp(arm.shoulder.rotation.y, side * 0.04, 10, dt);
      arm.elbow.rotation.x = THREE.MathUtils.damp(arm.elbow.rotation.x, -ex, 14, dt);
      arm.elbow.rotation.z = ez;
    }

    // Legs.
    for (const side of [-1, 1]) {
      const leg = side === -1 ? this.legs.left : this.legs.right;
      let hx = 0;
      let hz = side * 0.025;
      let kx = 0.05;

      if (this.pose.run > 0.01) {
        const run = Math.sin(t * 13 + (side === -1 ? 0 : Math.PI)) * 0.85 * this.pose.run;
        hx += run;
        kx += Math.max(0, -run) * 1.2 + 0.15;
        hz += side * 0.02;
      }
      if (this.pose.swing > 0.01) {
        hx += (side === 1 ? 0.5 : 0.28) * this.pose.swing;
        kx += (side === 1 ? 0.9 : 0.45) * this.pose.swing;
        hz += side * 0.1;
      }
      if (this.pose.fall > 0.01) {
        hx += side * 0.25 * this.pose.fall;
        kx += 0.5 * this.pose.fall;
        hz += side * 0.16 * this.pose.fall;
      }
      if (this.pose.strike > 0.01) {
        hx += (side === 1 ? 0.45 : -0.3) * this.pose.strike;
        kx += 0.55 * this.pose.strike;
      }

      leg.hip.rotation.x = THREE.MathUtils.damp(leg.hip.rotation.x, hx, 13, dt);
      leg.hip.rotation.z = THREE.MathUtils.damp(leg.hip.rotation.z, hz, 12, dt);
      leg.knee.rotation.x = THREE.MathUtils.damp(leg.knee.rotation.x, kx, 14, dt);
    }

    // Landing squash translated into a short crouch.
    if (grounded) {
      this.rig.position.y -= this.pose.fall * 0.05;
    }

    // Shadow.
    const hover = Math.max(0, this.root.position.y - (surfaceY ?? 0));
    this.shadow.position.set(this.root.position.x, (surfaceY ?? 0) + 0.035, this.root.position.z);
    const shadowScale = THREE.MathUtils.clamp(1 - hover / 40, 0.32, 1.4);
    this.shadow.scale.setScalar(shadowScale);
    this.shadow.material.opacity = THREE.MathUtils.clamp(0.55 - hover / 70, 0.08, 0.55);
    this.shadow.rotation.z = this.root.rotation.y;
  }

  getWorldPosition(target = new THREE.Vector3()) {
    return this.root.getWorldPosition(target);
  }
}

export class Goblin {
  constructor(scene) {
    this.scene = scene;
    this.root = new THREE.Group();
    this.root.name = 'GreenGoblin';
    this.scene.add(this.root);
    this.visual = new THREE.Group();
    this.root.add(this.visual);

    this.green = mat('#55a52b', { roughness: 0.5, flatShading: true, emissive: '#0a2303', emissiveIntensity: 0.3 });
    this.greenDark = mat('#2d631d', { roughness: 0.62, flatShading: true });
    this.purple = mat('#522887', { roughness: 0.42, metalness: 0.18, emissive: '#16052d', emissiveIntensity: 0.3 });
    this.purpleDark = mat('#281044', { roughness: 0.52 });
    this.yellow = mat('#ffe23b', { roughness: 0.22, emissive: '#ffcf00', emissiveIntensity: 1.25 });
    this.brown = mat('#4b3020', { roughness: 0.78 });
    this.black = mat('#0b0b0e', { roughness: 0.5 });
    this.time = 0;
    this.arms = {};
    this.headPivot = null;
    this.webWrap = null;
    this.bombHand = null;
    this.normalY = 0;
    this.buildGlider();
    this.buildGoblin();
    this.buildWebWrap();
  }

  buildGlider() {
    const glider = new THREE.Group();
    this.glider = glider;
    this.visual.add(glider);

    const deck = new THREE.Mesh(new THREE.BoxGeometry(1.5, 0.25, 3.2), this.purpleDark);
    deck.position.y = -0.05;
    glider.add(deck);

    const nose = new THREE.Mesh(new THREE.ConeGeometry(0.7, 1.8, 4), this.purple);
    nose.rotation.x = Math.PI / 2;
    nose.rotation.z = Math.PI / 4;
    nose.position.set(0, 0.05, -2.2);
    glider.add(nose);

    // Bat-wing glider surfaces.
    for (const side of [-1, 1]) {
      const shape = new THREE.Shape();
      shape.moveTo(0, 0.8);
      shape.lineTo(1.0, 0.65);
      shape.lineTo(4.6, 1.1);
      shape.lineTo(3.9, 0.1);
      shape.lineTo(4.8, -0.75);
      shape.lineTo(2.0, -0.5);
      shape.lineTo(0, -0.9);
      shape.closePath();
      const geo = new THREE.ExtrudeGeometry(shape, { depth: 0.13, bevelEnabled: true, bevelSize: 0.04, bevelThickness: 0.03, bevelSegments: 1 });
      geo.rotateX(-Math.PI / 2);
      const wing = new THREE.Mesh(geo, this.purple);
      wing.scale.x = side;
      wing.position.set(0, 0.06, 0);
      glider.add(wing);

      const trimShape = new THREE.Shape();
      trimShape.moveTo(0.85, 0.64);
      trimShape.lineTo(4.55, 1.05);
      trimShape.lineTo(3.9, 0.13);
      trimShape.lineTo(4.72, -0.72);
      const trimGeo = new THREE.BufferGeometry().setFromPoints(trimShape.getPoints());
      const trim = new THREE.Line(trimGeo, new THREE.LineBasicMaterial({ color: '#92ff73', transparent: true, opacity: 0.8 }));
      trim.rotation.x = Math.PI / 2;
      trim.scale.x = side;
      trim.position.y = 0.17;
      glider.add(trim);

      const engine = new THREE.Mesh(new THREE.CylinderGeometry(0.28, 0.36, 0.7, 8), this.black);
      engine.rotation.x = Math.PI / 2;
      engine.position.set(side * 0.55, -0.18, 1.25);
      glider.add(engine);
      const engineGlow = glowSprite(GLOW, '#7cff65', 2.8, 0.78);
      engineGlow.position.set(side * 0.55, -0.18, 1.7);
      glider.add(engineGlow);
      if (!this.engineGlows) this.engineGlows = [];
      this.engineGlows.push(engineGlow);
    }

    // Handle bars.
    for (const side of [-1, 1]) {
      const bar = new THREE.Mesh(new THREE.CylinderGeometry(0.055, 0.055, 0.85, 6), this.black);
      bar.position.set(side * 0.38, 0.45, -0.95);
      bar.rotation.x = 0.35;
      bar.rotation.z = side * 0.15;
      glider.add(bar);
    }

    const batEyes = new THREE.Mesh(new THREE.SphereGeometry(0.1, 7, 5), this.yellow);
    batEyes.position.set(0, 0.18, -2.9);
    glider.add(batEyes);
  }

  buildGoblin() {
    const body = new THREE.Group();
    body.position.y = 0.68;
    this.body = body;
    this.visual.add(body);

    // Legs astride glider.
    for (const side of [-1, 1]) {
      const leg = new THREE.Mesh(new THREE.CapsuleGeometry(0.13, 0.55, 4, 7), this.purple);
      leg.position.set(side * 0.28, 0.38, 0.1);
      leg.rotation.z = side * 0.4;
      leg.rotation.x = 0.2;
      body.add(leg);
      const boot = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.18, 0.42), this.greenDark);
      boot.position.set(side * 0.48, 0.04, 0.12);
      body.add(boot);
    }

    const torso = new THREE.Mesh(new THREE.CapsuleGeometry(0.36, 0.5, 5, 9), this.purple);
    torso.position.y = 1.25;
    torso.scale.set(1.05, 1, 0.82);
    body.add(torso);

    const tunic = new THREE.Mesh(new THREE.ConeGeometry(0.55, 0.85, 7), this.purpleDark);
    tunic.position.y = 0.95;
    tunic.rotation.y = 0.3;
    body.add(tunic);

    const belt = new THREE.Mesh(new THREE.TorusGeometry(0.34, 0.06, 4, 12), this.brown);
    belt.rotation.x = Math.PI / 2;
    belt.position.y = 1.09;
    body.add(belt);

    const satchel = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.34, 0.22), this.brown);
    satchel.position.set(-0.37, 1.02, 0.14);
    satchel.rotation.z = 0.16;
    body.add(satchel);

    // Shoulders / arms.
    for (const side of [-1, 1]) {
      const shoulder = new THREE.Group();
      shoulder.position.set(side * 0.43, 1.53, 0);
      body.add(shoulder);
      const upper = new THREE.Mesh(new THREE.CapsuleGeometry(0.115, 0.3, 4, 7), this.purple);
      upper.position.y = -0.22;
      shoulder.add(upper);
      const elbow = new THREE.Group();
      elbow.position.y = -0.44;
      shoulder.add(elbow);
      const forearm = new THREE.Mesh(new THREE.CapsuleGeometry(0.095, 0.26, 4, 7), this.green);
      forearm.position.y = -0.2;
      elbow.add(forearm);
      const hand = new THREE.Mesh(new THREE.SphereGeometry(0.12, 8, 6), this.greenDark);
      hand.position.y = -0.38;
      elbow.add(hand);
      this.arms[side === -1 ? 'left' : 'right'] = { shoulder, elbow, hand };
    }

    // Bomb held in left hand.
    const bomb = new THREE.Mesh(
      new THREE.SphereGeometry(0.2, 12, 9),
      new THREE.MeshStandardMaterial({ color: '#ff7418', roughness: 0.42, emissive: '#ff3a00', emissiveIntensity: 0.7 })
    );
    bomb.scale.y = 0.82;
    bomb.position.y = -0.42;
    const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.04, 0.13, 5), this.greenDark);
    stem.position.y = 0.2;
    bomb.add(stem);
    this.arms.left.hand.add(bomb);
    this.bombHand = bomb;

    // Head and hood.
    this.headPivot = new THREE.Group();
    this.headPivot.position.set(0, 1.93, 0);
    body.add(this.headPivot);
    const hood = new THREE.Mesh(new THREE.SphereGeometry(0.37, 12, 9), this.purple);
    hood.scale.set(1, 1.07, 0.92);
    hood.position.y = 0.24;
    this.headPivot.add(hood);

    const head = new THREE.Mesh(new THREE.SphereGeometry(0.28, 14, 10), this.green);
    head.scale.set(0.92, 1, 1.05);
    head.position.set(0, 0.19, 0.06);
    this.headPivot.add(head);

    // Nose, chin and manic grin.
    const nose = new THREE.Mesh(new THREE.ConeGeometry(0.075, 0.38, 6), this.greenDark);
    nose.rotation.x = Math.PI / 2;
    nose.position.set(0, 0.14, 0.37);
    this.headPivot.add(nose);
    const chin = new THREE.Mesh(new THREE.ConeGeometry(0.1, 0.18, 5), this.greenDark);
    chin.position.set(0, 0.01, 0.24);
    chin.rotation.x = Math.PI;
    this.headPivot.add(chin);

    for (const side of [-1, 1]) {
      // Pointed ears.
      const ear = new THREE.Mesh(new THREE.ConeGeometry(0.09, 0.44, 5), this.green);
      ear.position.set(side * 0.32, 0.26, 0.02);
      ear.rotation.z = side * -1.0;
      ear.rotation.x = 0.12;
      this.headPivot.add(ear);

      const eyeOutline = new THREE.Mesh(new THREE.SphereGeometry(0.08, 9, 7), this.black);
      eyeOutline.scale.set(1.6, 0.9, 0.22);
      eyeOutline.position.set(side * 0.1, 0.22, 0.28);
      eyeOutline.rotation.z = side * 0.32;
      this.headPivot.add(eyeOutline);
      const eye = new THREE.Mesh(new THREE.SphereGeometry(0.064, 9, 7), this.yellow);
      eye.scale.set(1.55, 0.8, 0.2);
      eye.position.set(side * 0.1, 0.225, 0.29);
      eye.rotation.z = side * 0.32;
      this.headPivot.add(eye);
    }

    // Grin.
    const mouth = new THREE.Mesh(new THREE.TorusGeometry(0.12, 0.015, 3, 12, Math.PI), this.black);
    mouth.rotation.x = Math.PI / 2;
    mouth.rotation.z = Math.PI;
    mouth.position.set(0, 0.07, 0.29);
    this.headPivot.add(mouth);

    // Hood peak.
    const peak = new THREE.Mesh(new THREE.ConeGeometry(0.2, 0.55, 6), this.purpleDark);
    peak.position.set(0, 0.62, -0.06);
    peak.rotation.x = -0.25;
    this.headPivot.add(peak);
  }

  buildWebWrap() {
    const wrap = new THREE.Group();
    const webMat = new THREE.MeshBasicMaterial({ color: '#e8f8ff', transparent: true, opacity: 0.88 });
    for (let i = 0; i < 10; i++) {
      const strand = new THREE.Mesh(new THREE.TorusGeometry(0.36 + i * 0.02, 0.012, 3, 18, Math.PI * 1.5), webMat);
      strand.rotation.set(Math.random() * TAU, Math.random() * TAU, Math.random() * TAU);
      strand.position.y = 1.15 + (Math.random() - 0.5) * 0.7;
      wrap.add(strand);
    }
    wrap.visible = false;
    this.root.add(wrap);
    this.webWrap = wrap;
  }

  update(dt, state = {}) {
    this.time += dt;
    const { position, yaw = 0, bank = 0, bobPhase = 0, stunned = false, bob = true, boss = false } = state;
    if (position) this.root.position.copy(position);
    this.visual.rotation.y = THREE.MathUtils.damp(this.visual.rotation.y, yaw, 5, dt);
    this.visual.rotation.z = THREE.MathUtils.damp(this.visual.rotation.z, bank, 5, dt);
    this.visual.rotation.x = THREE.MathUtils.damp(this.visual.rotation.x, -0.04 - Math.abs(bank) * 0.3, 5, dt);

    const t = this.time;
    const hover = bob ? Math.sin(t * 3.2 + bobPhase) * 0.18 : 0;
    this.glider.position.y = hover;
    this.body.position.y = 0.68 + hover * 0.8;
    this.glider.rotation.z = Math.sin(t * 1.8 + bobPhase) * 0.015;
    this.body.rotation.z = Math.sin(t * 1.5) * 0.02;

    // Idle engine pulse.
    if (this.engineGlows) {
      this.engineGlows.forEach((g, i) => {
        g.scale.setScalar(2.5 + Math.sin(t * 5 + i) * 0.3);
        g.material.opacity = 0.6 + Math.sin(t * 8 + i) * 0.17;
      });
    }

    // Stunned: arms flail and glider wobbles. Otherwise: evil crouch and throw flourish.
    const arms = this.arms;
    const cackle = stunned ? Math.sin(t * 12) * 0.1 : Math.sin(t * 2.2) * 0.03;
    arms.left.shoulder.rotation.x = THREE.MathUtils.damp(arms.left.shoulder.rotation.x, stunned ? -1.8 : 0.8, 8, dt);
    arms.left.shoulder.rotation.z = THREE.MathUtils.damp(arms.left.shoulder.rotation.z, stunned ? -0.7 : 0.2, 8, dt);
    arms.right.shoulder.rotation.x = THREE.MathUtils.damp(arms.right.shoulder.rotation.x, stunned ? -2.2 : -0.3, 8, dt);
    arms.right.shoulder.rotation.z = THREE.MathUtils.damp(arms.right.shoulder.rotation.z, stunned ? 0.7 : -0.2, 8, dt);
    arms.left.elbow.rotation.x = THREE.MathUtils.damp(arms.left.elbow.rotation.x, stunned ? -0.5 : -0.5, 8, dt);
    arms.right.elbow.rotation.x = THREE.MathUtils.damp(arms.right.elbow.rotation.x, stunned ? -0.8 : -0.8, 8, dt);

    this.headPivot.rotation.z = cackle;
    this.headPivot.rotation.y = stunned ? Math.sin(t * 7) * 0.12 : Math.sin(t * 0.8) * 0.12;
    this.headPivot.rotation.x = stunned ? -0.15 : Math.sin(t * 1.5) * 0.03;

    if (this.bombHand) {
      this.bombHand.visible = !stunned;
      this.bombHand.rotation.y += dt * 1.4;
      this.bombHand.material.emissiveIntensity = 0.55 + Math.sin(t * 6) * 0.35;
    }
    this.webWrap.visible = stunned;
    if (this.webWrap.visible) {
      this.webWrap.rotation.y += dt * 1.2;
      this.webWrap.rotation.z = Math.sin(t * 2) * 0.12;
    }
  }

  setPosition(position) {
    this.root.position.copy(position);
  }

  getWorldPosition(target = new THREE.Vector3()) {
    return this.root.getWorldPosition(target);
  }
}

export class HenchmanDrone {
  constructor(scene, position) {
    this.scene = scene;
    this.root = new THREE.Group();
    this.root.position.copy(position);
    this.scene.add(this.root);
    this.time = 0;
    this.baseY = position.y;
    this.alive = true;
    this.captured = false;
    this.capturedTimer = 0;

    this.green = mat('#4f982b', { flatShading: true });
    this.purple = mat('#49247a', { flatShading: true });
    this.black = mat('#080b12', { roughness: 0.4, metalness: 0.55 });
    this.blueGlow = new THREE.MeshBasicMaterial({ color: '#6be7ff' });
    this.redGlow = new THREE.MeshBasicMaterial({ color: '#ff2c42' });

    this.body = new THREE.Group();
    this.root.add(this.body);

    const torso = new THREE.Mesh(new THREE.CapsuleGeometry(0.3, 0.45, 4, 8), this.purple);
    torso.position.y = 1.2;
    this.body.add(torso);
    const head = new THREE.Mesh(new THREE.SphereGeometry(0.26, 10, 8), this.green);
    head.position.y = 1.73;
    head.scale.set(0.9, 1, 0.92);
    this.body.add(head);
    for (const side of [-1, 1]) {
      const ear = new THREE.Mesh(new THREE.ConeGeometry(0.06, 0.25, 4), this.green);
      ear.position.set(side * 0.24, 1.78, 0);
      ear.rotation.z = -side * 1.1;
      this.body.add(ear);
      const eye = new THREE.Mesh(new THREE.SphereGeometry(0.045, 7, 5), this.yellow ?? this.redGlow);
      eye.position.set(side * 0.08, 1.77, 0.23);
      this.body.add(eye);
    }
    const snout = new THREE.Mesh(new THREE.ConeGeometry(0.08, 0.2, 5), this.green);
    snout.rotation.x = Math.PI / 2;
    snout.position.set(0, 1.65, 0.26);
    this.body.add(snout);

    for (const side of [-1, 1]) {
      const arm = new THREE.Mesh(new THREE.CapsuleGeometry(0.08, 0.35, 4, 7), this.purple);
      arm.position.set(side * 0.35, 1.16, 0.02);
      arm.rotation.z = side * 0.2;
      this.body.add(arm);
      const hand = new THREE.Mesh(new THREE.SphereGeometry(0.08, 6, 5), this.green);
      hand.position.set(side * 0.4, 0.89, 0.05);
      this.body.add(hand);
    }
    for (const side of [-1, 1]) {
      const leg = new THREE.Mesh(new THREE.CapsuleGeometry(0.1, 0.34, 4, 7), this.purple);
      leg.position.set(side * 0.15, 0.63, 0);
      leg.rotation.z = side * 0.12;
      this.body.add(leg);
    }

    const board = new THREE.Mesh(new THREE.BoxGeometry(1.2, 0.14, 2.0), this.black);
    board.position.y = 0.12;
    this.root.add(board);
    const boardGlow = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.07, 1.2), this.blueGlow);
    boardGlow.position.y = 0.22;
    this.root.add(boardGlow);
    for (const side of [-1, 1]) {
      const thruster = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.24, 0.5, 7), this.black);
      thruster.rotation.x = Math.PI / 2;
      thruster.position.set(side * 0.42, 0.05, 0.65);
      this.root.add(thruster);
      const glow = glowSprite(GLOW, '#ff3d55', 1.5, 0.65);
      glow.position.set(side * 0.42, 0.05, 1.0);
      this.root.add(glow);
    }
    this.eyeGlow = glowSprite(GLOW, '#ff223c', 1.3, 0.5);
    this.eyeGlow.position.set(0, 1.77, 0.28);
    this.body.add(this.eyeGlow);
  }

  update(dt, playerPosition) {
    this.time += dt;
    if (this.captured) {
      this.capturedTimer += dt;
      this.root.position.y -= dt * (4 + this.capturedTimer * 9);
      this.root.rotation.z += dt * 5;
      this.root.rotation.x += dt * 2;
      if (this.root.position.y < 0.8) this.root.visible = false;
      return;
    }
    const bob = Math.sin(this.time * 2.6) * 0.4;
    this.root.position.y = this.baseY + bob;
    this.root.rotation.z = Math.sin(this.time * 1.5) * 0.07;
    this.root.rotation.y = Math.atan2(playerPosition.x - this.root.position.x, playerPosition.z - this.root.position.z);
    this.eyeGlow.material.opacity = 0.4 + Math.sin(this.time * 6) * 0.25;
  }

  capture() {
    this.captured = true;
    this.capturedTimer = 0;
  }
}

export class Citizen {
  constructor(scene, position, index) {
    this.scene = scene;
    this.position = position.clone();
    this.index = index;
    this.rescued = false;
    this.time = index * 0.7;
    this.root = new THREE.Group();
    this.root.position.copy(position);
    this.scene.add(this.root);

    const skin = mat(index % 2 === 0 ? '#bd7d55' : '#895634', { roughness: 0.75 });
    const shirtColors = ['#ffb23d', '#ef4059', '#43c9de', '#e7e1d2'];
    const shirt = mat(shirtColors[index % shirtColors.length], { roughness: 0.72 });
    const pants = mat('#172039', { roughness: 0.8 });

    const body = new THREE.Group();
    this.root.add(body);
    const legs = new THREE.Mesh(new THREE.CapsuleGeometry(0.09, 0.36, 3, 6), pants);
    legs.position.y = 0.55;
    body.add(legs);
    const torso = new THREE.Mesh(new THREE.CapsuleGeometry(0.18, 0.3, 4, 7), shirt);
    torso.position.y = 1.05;
    body.add(torso);
    const head = new THREE.Mesh(new THREE.SphereGeometry(0.17, 9, 7), skin);
    head.position.y = 1.42;
    body.add(head);
    const hair = new THREE.Mesh(new THREE.SphereGeometry(0.171, 9, 7, 0, TAU, 0, Math.PI * 0.55), mat(index % 2 ? '#1d1410' : '#4a2d18'));
    hair.position.y = 1.44;
    body.add(hair);

    for (const side of [-1, 1]) {
      const arm = new THREE.Mesh(new THREE.CapsuleGeometry(0.055, 0.28, 3, 6), shirt);
      arm.position.set(side * 0.23, 1.05, 0);
      arm.rotation.z = side * 0.15;
      body.add(arm);
    }
    const raisedArm = new THREE.Mesh(new THREE.CapsuleGeometry(0.055, 0.32, 3, 6), shirt);
    raisedArm.position.set(0.22, 1.34, 0);
    raisedArm.rotation.z = -1.9;
    body.add(raisedArm);

    // Rescue beacon.
    const beam = new THREE.Mesh(
      new THREE.CylinderGeometry(0.6, 1.7, 14, 12, 1, true),
      new THREE.MeshBasicMaterial({ color: '#6eeaff', transparent: true, opacity: 0.09, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending })
    );
    beam.position.y = 7;
    this.root.add(beam);
    this.beam = beam;
    const ring = new THREE.Mesh(
      new THREE.RingGeometry(1.2, 1.55, 30),
      new THREE.MeshBasicMaterial({ color: '#6eeaff', transparent: true, opacity: 0.55, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending })
    );
    ring.rotation.x = -Math.PI / 2;
    ring.position.y = 0.04;
    this.root.add(ring);
    this.ring = ring;
    const glow = glowSprite(GLOW, '#6eeaff', 4.5, 0.45);
    glow.position.y = 1.2;
    this.root.add(glow);
    this.glow = glow;
    this.body = body;
    this.raisedArm = raisedArm;
  }

  update(dt) {
    if (this.rescued) return;
    this.time += dt;
    const wave = Math.sin(this.time * 5) * 0.2;
    this.raisedArm.rotation.z = -1.9 + wave;
    this.body.position.y = Math.sin(this.time * 2.5) * 0.03;
    this.beam.material.opacity = 0.07 + Math.sin(this.time * 2.2) * 0.025;
    this.ring.scale.setScalar(1 + Math.sin(this.time * 1.7) * 0.08);
    this.glow.material.opacity = 0.35 + Math.sin(this.time * 4) * 0.12;
  }

  rescue() {
    this.rescued = true;
    this.root.visible = false;
  }
}

import * as THREE from 'three';

function glowTexture() {
  const canvas = document.createElement('canvas');
  canvas.width = 128;
  canvas.height = 128;
  const ctx = canvas.getContext('2d');
  const grad = ctx.createRadialGradient(64, 64, 0, 64, 64, 64);
  grad.addColorStop(0, 'rgba(255,255,255,1)');
  grad.addColorStop(0.2, 'rgba(255,255,255,0.8)');
  grad.addColorStop(0.5, 'rgba(255,255,255,0.2)');
  grad.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, 128, 128);
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function ringTexture() {
  const canvas = document.createElement('canvas');
  canvas.width = 256;
  canvas.height = 256;
  const ctx = canvas.getContext('2d');
  ctx.strokeStyle = 'rgba(255,255,255,1)';
  ctx.lineWidth = 9;
  ctx.beginPath();
  ctx.arc(128, 128, 100, 0, Math.PI * 2);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(255,255,255,0.35)';
  ctx.lineWidth = 24;
  ctx.beginPath();
  ctx.arc(128, 128, 100, 0, Math.PI * 2);
  ctx.stroke();
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

const GLOW = glowTexture();
const RING = ringTexture();

export class Effects {
  constructor(scene, camera) {
    this.scene = scene;
    this.camera = camera;
    this.glowTexture = GLOW;
    this.ringTexture = RING;
    this.poolSize = 700;
    this.positions = new Float32Array(this.poolSize * 3);
    this.colors = new Float32Array(this.poolSize * 3);
    this.particles = [];
    for (let i = 0; i < this.poolSize; i++) {
      this.particles.push({
        life: 0,
        maxLife: 1,
        velocity: new THREE.Vector3(),
        gravity: 0,
        drag: 0.98,
        baseColor: new THREE.Color(),
      });
      this.positions[i * 3 + 1] = -9999;
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(this.positions, 3));
    geo.setAttribute('color', new THREE.BufferAttribute(this.colors, 3));
    this.points = new THREE.Points(
      geo,
      new THREE.PointsMaterial({
        size: 1.0,
        vertexColors: true,
        transparent: true,
        opacity: 0.9,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        map: GLOW,
        alphaTest: 0.01,
        sizeAttenuation: true,
      })
    );
    this.points.frustumCulled = false;
    this.scene.add(this.points);
    this.cursor = 0;
    this.flashes = [];
    this.rings = [];
    this.lights = [];
    this.webs = [];
    this.trailTimers = new Map();
    this.time = 0;
  }

  spawn(origin, color, count = 8, options = {}) {
    const {
      speed = 7,
      spread = 1,
      upward = 0.3,
      size = 1,
      life = 0.6,
      gravity = -9,
      drag = 0.965,
      colorVariance = 0.4,
    } = options;
    const base = new THREE.Color(color);
    for (let n = 0; n < count; n++) {
      const i = this.cursor;
      this.cursor = (this.cursor + 1) % this.poolSize;
      const p = this.particles[i];
      p.life = life * (0.55 + Math.random() * 0.7);
      p.maxLife = p.life;
      p.gravity = gravity;
      p.drag = drag;
      p.baseColor.copy(base);
      const variance = (Math.random() - 0.5) * colorVariance;
      p.baseColor.offsetHSL(variance * 0.1, variance * 0.15, variance * 0.24);
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(2 * Math.random() - 1);
      const speedJitter = speed * (0.3 + Math.random() * 0.9);
      p.velocity.set(
        Math.sin(phi) * Math.cos(theta) * speedJitter * spread,
        Math.cos(phi) * speedJitter * 0.55 + upward * speed,
        Math.sin(phi) * Math.sin(theta) * speedJitter * spread
      );
      this.positions[i * 3] = origin.x + (Math.random() - 0.5) * 0.5;
      this.positions[i * 3 + 1] = origin.y + (Math.random() - 0.5) * 0.5;
      this.positions[i * 3 + 2] = origin.z + (Math.random() - 0.5) * 0.5;
      this.colors[i * 3] = p.baseColor.r;
      this.colors[i * 3 + 1] = p.baseColor.g;
      this.colors[i * 3 + 2] = p.baseColor.b;
      this.points.material.size = Math.max(this.points.material.size, size * 0.5);
    }
  }

  trail(id, position, color, options = {}) {
    const now = this.time;
    const last = this.trailTimers.get(id) || 0;
    if (now - last < (options.interval || 0.035)) return;
    this.trailTimers.set(id, now);
    this.spawn(position, color, options.count || 1, {
      speed: options.speed || 1.4,
      spread: options.spread || 0.7,
      upward: options.upward || 0,
      life: options.life || 0.45,
      gravity: options.gravity ?? 0.2,
      drag: 0.96,
      colorVariance: 0.5,
    });
  }

  impact(position, color = '#bdefff', count = 12, scale = 1) {
    this.spawn(position, color, count, { speed: 9 * scale, spread: 1, upward: 0.5, life: 0.42, gravity: -10 });
    this.spawn(position, '#ffffff', Math.floor(count / 3), { speed: 6 * scale, spread: 1, upward: 0.2, life: 0.22, gravity: 0 });
  }

  webSplat(position) {
    this.spawn(position, '#f2fbff', 20, { speed: 10, spread: 1, upward: 0.2, life: 0.7, gravity: -3.5 });
    const group = new THREE.Group();
    const mat = new THREE.LineBasicMaterial({ color: '#eefaff', transparent: true, opacity: 0.95 });
    for (let i = 0; i < 8; i++) {
      const angle = (i / 8) * Math.PI * 2 + Math.random() * 0.4;
      const points = [
        new THREE.Vector3(0, 0, 0),
        new THREE.Vector3(Math.cos(angle) * (0.6 + Math.random() * 0.7), Math.sin(angle) * (0.6 + Math.random() * 0.7), 0),
      ];
      const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(points), mat);
      line.rotation.z = Math.random() * Math.PI;
      group.add(line);
    }
    group.position.copy(position);
    this.scene.add(group);
    this.webs.push({ group, life: 1.4, maxLife: 1.4 });
  }

  explosion(position, scale = 1) {
    this.spawn(position, '#ffcf5c', 30, { speed: 17 * scale, spread: 1, upward: 0.6, life: 0.7, gravity: -3, colorVariance: 1 });
    this.spawn(position, '#ff5c1c', 38, { speed: 12 * scale, spread: 1, upward: 0.4, life: 0.9, gravity: -1.5, colorVariance: 0.8 });
    this.spawn(position, '#8f2b14', 25, { speed: 6 * scale, spread: 1, upward: 1.1, life: 1.5, gravity: 1.4, colorVariance: 0.3 });
    this.spawn(position, '#f7fbff', 10, { speed: 20 * scale, spread: 1, upward: 0.2, life: 0.24, gravity: 0 });

    const flash = new THREE.Sprite(
      new THREE.SpriteMaterial({ map: GLOW, color: '#ffd18b', transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false })
    );
    flash.position.copy(position);
    flash.scale.setScalar(6 * scale);
    this.scene.add(flash);
    this.flashes.push({ mesh: flash, life: 0.38, maxLife: 0.38, size: 28 * scale, color: '#ffd18b' });

    const ring = new THREE.Sprite(
      new THREE.SpriteMaterial({ map: RING, color: '#ffb55f', transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false })
    );
    ring.position.copy(position);
    ring.scale.setScalar(3 * scale);
    this.scene.add(ring);
    this.rings.push({ mesh: ring, life: 0.62, maxLife: 0.62, from: 2 * scale, to: 18 * scale, color: '#ffb55f' });

    const light = new THREE.PointLight('#ff7d32', 160 * scale, 60, 2);
    light.position.copy(position);
    this.scene.add(light);
    this.lights.push({ light, life: 0.32, maxLife: 0.32, intensity: 160 * scale });
  }

  shockwave(position, color = '#7cff65', scale = 1) {
    const ring = new THREE.Sprite(
      new THREE.SpriteMaterial({ map: RING, color, transparent: true, opacity: 0.75, blending: THREE.AdditiveBlending, depthWrite: false })
    );
    ring.position.copy(position);
    ring.scale.setScalar(5 * scale);
    this.scene.add(ring);
    this.rings.push({ mesh: ring, life: 1.1, maxLife: 1.1, from: 4 * scale, to: 46 * scale, color });
    this.spawn(position, color, 24, { speed: 13 * scale, spread: 1, upward: 0, life: 0.7, gravity: 0 });
  }

  dust(position, scale = 1) {
    this.spawn(position, '#b7c4d6', 13, {
      speed: 4.5 * scale,
      spread: 1,
      upward: 0.5,
      life: 0.8,
      gravity: -1,
      colorVariance: 0.2,
    });
  }

  update(dt) {
    this.time += dt;
    for (let i = 0; i < this.poolSize; i++) {
      const p = this.particles[i];
      if (p.life <= 0) continue;
      p.life -= dt;
      if (p.life <= 0) {
        this.positions[i * 3 + 1] = -9999;
        continue;
      }
      p.velocity.y += p.gravity * dt;
      p.velocity.multiplyScalar(Math.pow(p.drag, dt * 60));
      this.positions[i * 3] += p.velocity.x * dt;
      this.positions[i * 3 + 1] += p.velocity.y * dt;
      this.positions[i * 3 + 2] += p.velocity.z * dt;
      const a = Math.max(0, p.life / p.maxLife);
      const fade = a * a;
      this.colors[i * 3] = p.baseColor.r * fade;
      this.colors[i * 3 + 1] = p.baseColor.g * fade;
      this.colors[i * 3 + 2] = p.baseColor.b * fade;
    }
    this.points.geometry.attributes.position.needsUpdate = true;
    this.points.geometry.attributes.color.needsUpdate = true;

    for (let i = this.flashes.length - 1; i >= 0; i--) {
      const f = this.flashes[i];
      f.life -= dt;
      const a = Math.max(0, f.life / f.maxLife);
      f.mesh.material.opacity = a * 0.95;
      const s = THREE.MathUtils.lerp(f.size, f.size * 0.25, 1 - a);
      f.mesh.scale.setScalar(s);
      if (f.life <= 0) {
        this.scene.remove(f.mesh);
        f.mesh.material.dispose();
        this.flashes.splice(i, 1);
      }
    }

    for (let i = this.rings.length - 1; i >= 0; i--) {
      const r = this.rings[i];
      r.life -= dt;
      const t = 1 - Math.max(0, r.life / r.maxLife);
      const eased = 1 - Math.pow(1 - t, 2);
      r.mesh.scale.setScalar(THREE.MathUtils.lerp(r.from, r.to, eased));
      r.mesh.material.opacity = (1 - t) * 0.85;
      if (r.life <= 0) {
        this.scene.remove(r.mesh);
        r.mesh.material.dispose();
        this.rings.splice(i, 1);
      }
    }

    for (let i = this.lights.length - 1; i >= 0; i--) {
      const l = this.lights[i];
      l.life -= dt;
      const a = Math.max(0, l.life / l.maxLife);
      l.light.intensity = l.intensity * a * a;
      if (l.life <= 0) {
        this.scene.remove(l.light);
        this.lights.splice(i, 1);
      }
    }

    for (let i = this.webs.length - 1; i >= 0; i--) {
      const w = this.webs[i];
      w.life -= dt;
      const a = Math.max(0, w.life / w.maxLife);
      w.group.children.forEach((line) => {
        if (line.material) line.material.opacity = a;
      });
      w.group.scale.setScalar(1 + (1 - a) * 0.25);
      if (w.life <= 0) {
        this.scene.remove(w.group);
        w.group.children.forEach((line) => line.geometry.dispose());
        this.webs.splice(i, 1);
      }
    }
  }

  dispose() {
    this.scene.remove(this.points);
    this.points.geometry.dispose();
    this.points.material.dispose();
  }
}

