    this.touchMode = window.matchMedia('(pointer: coarse)').matches;
    this.isMobile = window.matchMedia('(max-width: 640px)').matches;
    this.gamepadButtons = [];
    this.joystick = { active: false, pointerId: null, x: 0, y: 0 };
