+    this.audio.sfx('ui');
+  },
+
+  restartLevel() {
+    if (!this.level) return;
+    this.ui.showPause(false);
+    this.ui.hidePanels();
+    this.startLevel(this.levelIndex, true);
+  },
+
+  retryLevel() {
+    this.ui.hidePanels();
+    if (!this.run || this.run.lives <= 0) {
+      this.startNewRun();
+      return;
