/* ---------------- HUD ---------------- */

.hud {
  position: absolute;
  inset: 0;
  z-index: 15;
  pointer-events: none;
  padding: var(--safe-top) 34px var(--safe-bottom);
  transition: opacity 0.35s ease;
}

.hud-top {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: start;
  gap: 24px;
  max-width: 1440px;
  margin: 0 auto;
}

.mission-card {
  justify-self: start;
  position: relative;
  padding: 12px 18px 12px 16px;
  min-width: 300px;
  border-left: 2px solid var(--red);
  background: linear-gradient(90deg, rgba(5, 10, 22, 0.78), rgba(5, 10, 22, 0.12));
}

.chapter-label,
.micro-label,
.eyebrow {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.22em;
  color: var(--muted);
  text-transform: uppercase;
}

.chapter-label {
  color: var(--red-hot);
  margin-bottom: 5px;
}

.objective-row {
  display: flex;
  align-items: center;
  gap: 9px;
  font-family: var(--font-display);
  font-size: clamp(17px, 1.5vw, 22px);
  line-height: 1;
  letter-spacing: 0.055em;
  text-transform: uppercase;
}

.objective-pip {
  width: 7px;
  height: 7px;
  flex: none;
  border-radius: 50%;
  background: var(--red);
  box-shadow: 0 0 0 4px rgba(255, 41, 72, 0.16), 0 0 16px var(--red);
  animation: pipPulse 1.8s ease-in-out infinite;
}

@keyframes pipPulse {
  50% {
    box-shadow: 0 0 0 7px rgba(255, 41, 72, 0), 0 0 22px var(--red);
  }
}

.chase-clock {
  text-align: center;
  min-width: 150px;
  padding: 8px 22px 9px;
  background: linear-gradient(180deg, rgba(5, 10, 22, 0.75), rgba(5, 10, 22, 0.2));
  border-top: 1px solid rgba(255, 255, 255, 0.1);
}

.chase-clock strong {
  display: block;
  font-family: var(--font-display);
  font-size: 34px;
  font-weight: 600;
  line-height: 0.95;
  letter-spacing: 0.08em;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 0 24px rgba(112, 231, 255, 0.28);
}

.chase-clock.is-critical strong {
  color: var(--red-hot);
  animation: clockPulse 1s ease-in-out infinite;
}

@keyframes clockPulse {
  50% {
    opacity: 0.5;
    transform: scale(1.04);
  }
}

.score-card {
  justify-self: end;
  text-align: right;
  padding: 8px 0 8px 18px;
}

.score-card strong {
  display: block;
  font-family: var(--font-display);
  font-size: 32px;
  font-weight: 600;
  letter-spacing: 0.08em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 0 20px rgba(255, 207, 92, 0.2);
}

.status-rail {
  position: absolute;
  left: 34px;
  bottom: var(--safe-bottom);
  width: 252px;
  padding: 16px 18px 14px;
  background: linear-gradient(100deg, rgba(6, 11, 23, 0.83), rgba(6, 11, 23, 0.3));
  border-left: 2px solid rgba(112, 231, 255, 0.42);
  clip-path: polygon(0 0, 100% 0, 94% 100%, 0 100%);
  backdrop-filter: blur(8px);
}

.status-title {
  display: flex;
  justify-content: space-between;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.18em;
  color: var(--muted);
  margin-bottom: 5px;
}

